\centering
\includegraphics[scale=0.3]{figure1.eps}\vspace{-5mm}
\caption{Heterogeneous material systems within star-configured regions}
\label{fig:domain0}
\end{figure}

To formulate the inverse elasticity problem for anisotropic composite materials as a regularized minimization problem. Let $u[a]$ denote the solution to \eqref{composite-eq} corresponding to the anisotropic coefficient tensor $a$. Given our focus on scenarios involving discontinuous anisotropic coefficients across material interfaces, we make the following key assumption
\begin{equation}
a\in\Lambda := \left\{ a\text{ is a self-adjoint matrix with strictly positive spectrum } | \text{TV}(a) < \infty \right\},
\end{equation}
where $\text{TV}(\cdot)$ denotes the TV semi-norm \cite{vogel2002computational}. In the heterogeneous and anisotropic elastic parameter estimation problem with full-field displacement measurements. Considering noise-perturbed measurement data $z(x, y)$ of the true displacement field $u[a^{\star}](x, y)$, where $a^{\star} \in \Lambda$ represents the unknown true anisotropic parameter tensor and $(x, y) \in \Omega$ spans the spatial domain.

To reconstruct $a^{\star}$, set
$$
\begin{aligned}
&J_0(a) = \frac{1}{2} \iint_{\Omega} \bigg( a_{11}(\frac{\partial(u_1[a]-z_1)}{\partial x})^2+a_{22}(\frac{\partial(u_2[a]-z_2)}{\partial y})^2+a_{33}(\frac{\partial(u_1[a]-z_1)}{\partial y}+\\
&\frac{\partial(u_2[a]-z_2)}{\partial x})^2 +2a_{12}\frac{\partial(u_1[a]-z_1)}{\partial x}\frac{\partial(u_2[a]-z_2)}{\partial y}+ 2a_{13}\frac{\partial(u_1[a]-z_1)}{\partial x}(\frac{\partial(u_2[a]-z_2)}{\partial x}\\
&+\frac{\partial(u_1[a]-z_1)}{\partial y})
+2a_{23}\frac{\partial(u_2[a]-z_2)}{\partial y}(\frac{\partial(u_2[a]-z_2)}{\partial x}+\frac{\partial(u_1[a]-z_1)}{\partial y}) \bigg) dxdy.
\end{aligned}
$$
Since computing the functional gradient of $J_0(a)$ does not require evaluating partial derivatives of the displacement field $u$ with respect to the anisotropic parameters $a$, this approach offers significant computational advantages. Each gradient evaluation requires solving just one forward elastic problem (Navier's equations), avoiding the need for additional adjoint-state solutions.
Consider
\begin{equation} \label{minpro}
\begin{aligned}
\min_{a \in \Lambda}J(a):= J_0(a) + \eta  \text{TV}(a) ,
\end{aligned}
\end{equation}
where $\eta > 0$ is the regularization parameter.
\begin{thm}\label{theory 1}
The minimization problem \eqref{minpro} exists at least one solution $a^0\in \Lambda$. 
\end{thm}
This result follows from Theorem 4.3 in \cite{part1} with our anisotropic elasticity setting.

When considering the problem in the curvilinear coordinate system \eqref{coordinate}, we assume that the true coefficient $a^{\star}$  is constant along radial ($\rho$) directions for each fixed angular $\phi$. In the angular ($\phi$) direction, $a^{\star}$ is piecewise constant with material interfaces at predetermined angles. Let $h = \max \limits_{0 \leq i< m} |\varphi_{i+1} - \varphi_i|$ and $0 = \varphi_0 < \varphi_1 < \ldots < \varphi_m = 2\pi$,
\begin{equation} \label{discrete admissible set}
\Lambda_h = \left\{ a_h(\rho, \phi) \in \Lambda \Bigg{|}
\begin{aligned}
& a_h \text{ maintains constant values almost surely} \\
& \text{in } (-\infty,0] \times [\varphi_i, \varphi_{i+1}) 
\end{aligned}
 \right\}.
\end{equation}
 Approximating the continuous problem \eqref{minpro} through the following discretization scheme
\begin{equation} \label{num-minpro}
\begin{aligned}
\min_{a_h \in \Lambda_h} J(a_h)  = J_0(a_h)+ \eta  \text{TV}(a_h).
\end{aligned}
\end{equation}
\begin{thm} \label{theory 2}
The discrete minimization problem \eqref{num-minpro} admits a solution $a_h^0 \in \Lambda_h$.
\end{thm}
which follows from Theorem \ref{theory 1} by observing the discrete space $\Lambda_h$ remains $L^1$-closed within the continuous space $\Lambda$.

Then we use the Adam algorithm \cite{Kingma2015} to solve the minimization problem \eqref{num-minpro}. Assume
\begin{equation} \label{discrete Lame coefficients}
a^h_{ij}(\rho, \phi) = \mathbbm{1}_{(-\infty, 0]}(\rho) \sum_{t = 1}^m a_{ij}^t \mathbbm{1}_{[\varphi_{t - 1},\varphi_t)}(\phi), i,j=1,2,3.
\end{equation}
And then
$$
\text{TV}(a_{ij}^h) = \sum_{t=1}^{m} \tilde{r}(\varphi_t) |a_{ij}^{t+1}-a_{ij}^t|,
$$
where $a_{ij}^{m + 1} = a_{ij}^1$. For the implementation of the Adam algorithm to solve \eqref{num-minpro}, the optimization procedure necessitates evaluating $\nabla J$, which in turn requires calculating $\nabla[\text{TV}(a_{ij}^h)]$. For $t=1, \ldots, m$,
\[
\frac {\partial TV(a_{ij}^h)}{\partial a_{ij}^t}=sgn(a_{ij}^t-a_{ij}^{t-1})\tilde{r}(\theta_{j-1})+sgn(a_{ij}^{t+1}-a_{ij}^t)\tilde{r}(\theta_{j}),
\]
where $a_{ij}^0 = a_{ij}^m, a_{ij}^{m + 1} = a_{ij}^1$ and $sgn(x)$ is the sign function.
Using the chain rule, we obtain
$$
\begin{aligned}
\frac {\partial J_0}{\partial a_{11}^t} &  = \int_{-\infty}^0 \int_{\varphi_{t-1}}^{\varphi_t} \frac12 ((\frac{\partial z_1}{\partial x})^2-(\frac{\partial u_1[a_h]}{\partial x})^2) e^{2\rho} \tilde{r}(\phi)^2 d\phi d\rho, \\
\frac {\partial J_0}{\partial a_{22}^t} &  = \int_{-\infty}^0 \int_{\varphi_{t-1}}^{\varphi_t} \frac12 ((\frac{\partial z_2}{\partial y})^2-(\frac{\partial u_2[a_h]}{\partial y})^2) e^{2\rho} \tilde{r}(\phi)^2 d\phi d\rho, \\
\frac {\partial J_0}{\partial a_{33}^t} &  = \int_{-\infty}^0 \int_{\varphi_{t-1}}^{\varphi_t} \frac12 ((\frac{\partial z_1}{\partial y}+\frac{\partial z_2}{\partial x})^2-(\frac{\partial u_1[a_h]}{\partial y}+\frac{\partial u_2[a_h]}{\partial x})^2) e^{2\rho} \tilde{r}(\phi)^2 d\phi d\rho, \\
\frac {\partial J_0}{\partial a_{12}^t} &  = \int_{-\infty}^0 \int_{\varphi_{t-1}}^{\varphi_t} (\frac{\partial z_1}{\partial x}\frac{\partial z_2}{\partial y}-\frac{\partial u_1[a_h]}{\partial x}\frac{\partial u_2[a_h]}{\partial y}) e^{2\rho} \tilde{r}(\phi)^2 d\phi d\rho, \\
\frac {\partial J_0}{\partial a_{13}^t} &  = \int_{-\infty}^0 \int_{\varphi_{t-1}}^{\varphi_t} (\frac{\partial z_1}{\partial x}(\frac{\partial z_2}{\partial x}+\frac{\partial z_1}{\partial y})-\frac{\partial u_1[a_h]}{\partial x}(\frac{\partial u_2[a_h]}{\partial x}+\frac{\partial u_1[a_h]}{\partial y})) e^{2\rho} \tilde{r}(\phi)^2 d\phi d\rho, \\
\frac {\partial J_0}{\partial a_{23}^t} &  = \int_{-\infty}^0 \int_{\varphi_{t-1}}^{\varphi_t} (\frac{\partial z_2}{\partial y}(\frac{\partial z_2}{\partial x}+\frac{\partial z_1}{\partial y})-\frac{\partial u_2[a_h]}{\partial y}(\frac{\partial u_2[a_h]}{\partial x}+\frac{\partial u_1[a_h]}{\partial y})) e^{2\rho} \tilde{r}(\phi)^2 d\phi d\rho.
\end{aligned}
$$
Hence for $t=1, \ldots, m$
\begin{equation} \label{gradient of J}
\frac {\partial J}{\partial a_{ij}^t}=\frac {\partial J_0}{\partial a_{ij}^t} + \eta\frac {\partial \text{TV}(a_{ij}^h)}{\partial a_{ij}^t}.
\end{equation}

From the preceding analysis, evaluating the objective functional $J(a_h)$ and its gradient requires computing the displacement field $u[a_h]$ for discrete parameters $a_h \in \Lambda_h$. Two critical challenges arise in this computation: (1) $u[a_h]$ potentially contains singular stress behavior at material interface junctions and the geometric singularity point (where all interfaces $L_k$ meet), (2)the star-configured regions $\Omega$ displays inherent geometrical irregularities. Hence the forward solver is a novel semi-analytical scheme named the direct method of lines, chosen for its ability to handle stress singularities via semi-analytic separation of variables and natural compatibility with curvilinear coordinates \eqref{coordinate}, avoiding mesh generation difficulties for irregular geometries.


Denote $\mathscr{L} = (a_{11}^1, \cdots,a_{11}^m,a_{22}^1, \cdots,a_{22}^m,a_{33}^1, \cdots,a_{33}^m,a_{12}^1, \cdots,a_{12}^m,a_{13}^1, \cdots,a_{13}^m,$
$a_{23}^1, \cdots,a_{23}^m)^T,$ 
$
\mathcal{G} = ( \frac {\partial J}{\partial a_{11}^1}, \cdots, \frac {\partial J}{\partial a_{11}^m}, \frac {\partial J}{\partial a_{22}^1}, \cdots, \frac {\partial J}{\partial a_{22}^m},\frac {\partial J}{\partial a_{33}^1}, \cdots, \frac {\partial J}{\partial a_{33}^m},\frac {\partial J}{\partial a_{12}^1}, \cdots, \frac {\partial J}{\partial a_{12}^m},$
$\frac {\partial J}{\partial a_{13}^1}, \cdots, \frac {\partial J}{\partial a_{13}^m}, \frac {\partial J}{\partial a_{23}^1}, \cdots, \frac {\partial J}{\partial a_{23}^m})^T.
$
At the $k$-th iteration, we assign $\mathscr{L}^k$ as the current value of $\mathscr{L}$,   $a_h^k $ be the coefficients \eqref{discrete Lame coefficients} associated with $\mathscr{L}^k$, $\mathcal{G}^k$ represents $\mathcal{G}$ associated with the coefficients $a_h^k$. The Adam algorithm using the semi-analytical forward solver for heterogeneous and anisotropic elastic parameter estimation is similar to Algorithm 1 in \cite{zhu2023}.
