&=\frac1{e^{\rho}\tilde{r}^2}\bigg(a_{11}^k(\frac{\partial u_1^k}{\partial\rho}(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))+\frac{\partial u_1^k}{\partial\phi}(-\tilde{r}\sin{\phi}))+a_{12}^k(\frac{\partial u_2^k}{\partial\rho}\\
&(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))+\frac{\partial u_2^k}{\partial\phi}(\tilde{r}\cos{\phi}))+a_{13}^k(\frac{\partial u_1^k}{\partial\rho}(-\tilde{r}'\cos(\phi)\\
&+\tilde{r}\sin(\phi))+\frac{\partial u_1^k}{\partial\phi}(\tilde{r}\cos{\phi})
+\frac{\partial u_2^k}{\partial\rho}(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))+\frac{\partial u_2^k}{\partial\phi}(-\tilde{r}\sin{\phi})\bigg),
\end{aligned} 
\end{equation}
\begin{equation} 
\begin{aligned}
\sigma^k_{22} &=a_{12}^k\frac{\partial u_1^k}{\partial x}+a_{22}^k\frac{\partial u_2^k}{\partial y}+a_{23}^k(\frac{\partial u_1^k}{\partial y}+\frac{\partial u_2^k}{\partial x})\\
&=\frac1{e^{\rho}\tilde{r}^2}\bigg(a_{12}^k(\frac{\partial u_1^k}{\partial\rho}(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))+\frac{\partial u_1^k}{\partial\phi}(-\tilde{r}\sin{\phi}))+a_{22}^k(\frac{\partial u_2^k}{\partial\rho}\\
&(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))+\frac{\partial u_2^k}{\partial\phi}(\tilde{r}\cos{\phi}))+a_{23}^k(\frac{\partial u_1^k}{\partial\rho}(-\tilde{r}'\cos(\phi)\\
&+\tilde{r}\sin(\phi))+\frac{\partial u_1^k}{\partial\phi}(\tilde{r}\cos{\phi})+\frac{\partial u_2^k}{\partial\rho}(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))+\frac{\partial u_2^k}{\partial\phi}(-\tilde{r}\sin{\phi})\bigg),
\end{aligned}
\end{equation}
