\begin{aligned}
\sigma^k_{12} &=\sigma^k_{21}=a_{13}^k\frac{\partial u_1^k}{\partial x}+a_{23}^k\frac{\partial u_2^k}{\partial y}+a_{33}^k(\frac{\partial u_1^k}{\partial y}+\frac{\partial u_2^k}{\partial x})\\
&=\frac1{e^{\rho}\tilde{r}^2}\bigg(a_{13}^k(\frac{\partial u_1^k}{\partial\rho}(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))+\frac{\partial u_1^k}{\partial\phi}(-\tilde{r}\sin{\phi}))+a_{23}^k(\frac{\partial u_2^k}{\partial\rho}\\
&(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))+\frac{\partial u_2^k}{\partial\phi}(\tilde{r}\cos{\phi}))+a_{33}^k(\frac{\partial u_1^k}{\partial\rho}(-\tilde{r}'\cos(\phi)\\
&+\tilde{r}\sin(\phi))+\frac{\partial u_1^k}{\partial\phi}(\tilde{r}\cos{\phi})+\frac{\partial u_2^k}{\partial\rho}(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))+\frac{\partial u_2^k}{\partial\phi}(-\tilde{r}\sin{\phi})\bigg).
\end{aligned}
\end{equation}
In $\Omega_k$, the original problem \eqref{composite-eq} can now be reformulated as :
\begin{equation} \label{discontinuous-composite-eq}
\begin{aligned}
&((\tilde{r}'sin(\phi)+\tilde{r}cos(\phi))\frac{\partial}{\partial \rho}-\tilde{r}sin(\phi)\frac{\partial}{\partial \phi})\sigma_{11}^k\\
&+((-\tilde{r}'cos(\phi)+\tilde{r}sin(\phi))\frac{\partial}{\partial \rho}+\tilde{r}cos(\phi)\frac{\partial}{\partial \phi})\sigma_{12}^k  = 0,\\
&((\tilde{r}'sin(\phi)+\tilde{r}cos(\phi))\frac{\partial}{\partial \rho}-\tilde{r}sin(\phi)\frac{\partial}{\partial \phi})\sigma_{12}^k\\
&+((-\tilde{r}'cos(\phi)+\tilde{r}sin(\phi))\frac{\partial}{\partial \rho}+\tilde{r}cos(\phi)\frac{\partial}{\partial \phi})\sigma_{22}^k  = 0,\\
 &u^k(0,\phi)=f^k(\phi), \quad u^{k - 1}(\rho,\theta_k^-) = u^{k}(\rho,\theta_k^+),\\
&\left(
\begin{matrix}
\sigma^{k - 1}_{11} \sin(\theta_k) - \sigma^{k-1}_{12} \cos(\theta_k) \\
\sigma^{k - 1}_{21} \sin(\theta_k) - \sigma^{k-1}_{22} \cos(\theta_k)
\end{matrix}\right)  = \left(
\begin{matrix}
\sigma^{k}_{11} \sin(\theta_k) - \sigma^{k}_{12} \cos(\theta_k) \\
\sigma^{k}_{21} \sin(\theta_k) - \sigma^{k}_{22} \cos(\theta_k)
\end{matrix}\right),\\
&u \text{ is bounded,} \text{ when } \rho\rightarrow -\infty. 
\end{aligned}
\end{equation}

 Denote $H^1_p(0, 2\pi)$ as the periodic Sobolev space, $V = H^1_p(0, 2\pi) \times H^1_p(0, 2\pi)$ and $W = \{w(\rho,\phi)|w, \partial_{\rho} w, \partial^2_{\rho\rho} w \in V , \forall\rho < 0 \}$.  Problem \eqref{discontinuous-composite-eq} can be equivalently expressed as
\begin{equation} \label{v-d-problem}
\begin{aligned}
& \text{determine } u\in W, \text{ s.t. }\forall v\in V,-\infty <\rho<0, \\
& \frac{d^2A_2(u,v)}{d\rho^2}+\frac{dA_1(u,v)}{d\rho}+A_0(u,v)=0,\\
& u(-\infty,\phi) <\infty, \quad u(0,\phi)=f(\phi),
\end{aligned}
\end{equation}
with
\begin{equation}
A_0(u,v) = -\sum_{k = 1}^K \int_{\theta_k}^{\theta_{k+1}} \left( \frac{\partial u^k (\rho, \phi)}{\partial \phi} \right)^T \Psi^k_0\frac{d v^k}{d\phi} d\phi,
\end{equation}
\begin{equation}
A_1(u,v) = \sum_{k = 1}^K \int_{\theta_k}^{\theta_{k+1}} \left( \left( \frac{\partial u^k (\rho, \phi) }{\partial \phi} \right)^T \Psi^k_1 v^k - u^k(\rho,\phi)^T (\Psi_1^k)^T \frac{d v^k}{d\phi} \right) d\phi,
\end{equation}
\begin{equation}
A_2(u,v) = \sum_{k = 1}^K \int_{\theta_k}^{\theta_{k+1}} u^k(\rho,\phi)^T \Psi_2^k v^k d\phi,
\end{equation}
where $v^k = v|_{[\theta_k,\theta_{k+1}]}$ and
$$
\begin{aligned}
\Psi_2^k = \frac1{\tilde{r}^2}\left(
\begin{matrix}
a_{11}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))^2 & a_{13}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))^2\\
+2a_{13}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi)) & +(a_{33}^k+a_{12}^k)(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))\\
(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi)) & (-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))\\
+a_{33}^k(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))^2 &+a_{23}^k(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))^2\\
\\
a_{13}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))^2 &  a_{33}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))^2\\
+(a_{33}^k+a_{12}^k)(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))& +2a_{23}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi)) \\
(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))& (-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))\\
+a_{23}^k(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))^2&  +a_{22}^k(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))^2
\end{matrix}\right), 
\end{aligned}
$$
$$
\Psi_1^k = \frac1{\tilde{r}}\left(
\begin{matrix}
-a_{11}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))\sin(\phi) & -a_{13}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))\sin(\phi) \\
+a_{13}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))\cos(\phi)& +a_{12}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))\cos(\phi)\\
-a_{13}^k(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))\sin(\phi)&-a_{33}^k(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))\sin(\phi)\\
+a_{33}^k(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))\cos(\phi)&+a_{23}^k(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))\cos(\phi)\\
\\
-a_{13}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))\sin(\phi) & -a_{33}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))\sin(\phi) \\
+a_{33}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))\cos(\phi)& +a_{23}^k(\tilde{r}'\sin(\phi)+\tilde{r}\cos(\phi))\cos(\phi)\\
-a_{12}^k(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))\sin(\phi)&-a_{23}^k(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))\sin(\phi)\\
+a_{23}^k(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))\cos(\phi)&+a_{22}^k(-\tilde{r}'\cos(\phi)+\tilde{r}\sin(\phi))\cos(\phi)
\end{matrix}\right), 
$$
$$
\Psi_0^k = \left(
\begin{matrix}
a_{11}^k\sin^2(\phi)+a_{33}^k\cos^2(\phi)& a_{13}^k\sin^2(\phi)+a_{23}^k\cos^2(\phi)\\
-2a_{13}^k\cos(\phi)\sin(\phi)& -(a_{33}^k+a_{12}^k)\cos(\phi)\sin(\phi) \\
\\
a_{13}^k\sin^2(\phi)+a_{23}^k\cos^2(\phi)& a_{33}^k\sin^2(\phi)+a_{22}^k\cos^2(\phi)\\
-(a_{33}^k+a_{12}^k)\cos(\phi)\sin(\phi)&-2a_{23}^k\cos(\phi)\sin(\phi)
\end{matrix}\right).
$$
\begin{lemma}\label{lem:A} The following properties hold for the three bounded bilinear forms $A_j$ on $V\times V$:\\
(1) $A_0$ and $A_2$ are symmetric, while $A_1$ is antisymmetric.\\
(2) There exists a constant $c>0$ such that
\[
-A_0(v,v)\geq c|| v^{\prime} ||_2^2,\quad A_2(v,v)\geq c || v ||_2^2, \quad \forall v \in V.
\]
where $|| \cdot ||_2$ is the $L^2$ norm and $v^{\prime}$ is the weak derivative of $v$. 
\end{lemma}

\subsection{Semi-analytical treatment}
To numerically solve  variational-differential problem \eqref{v-d-problem},
let $[0,2\pi]$ be partitioned into $M$ subintervals with nodes $0 = \phi_1 < \ldots < \phi_{M + 1} = 2\pi$, such that all material interface angles $\{\theta_k\}_{k = 1}^K$ are included in the nodal set and $h = \max_{1 \le j \le M} |\phi_{j+1}-\phi_j|$.  Choose $V_1^h\subset H^1_p(0, 2\pi)$ to be $P_1$-conforming linear finite element space, $V^h = V_1^h \times V_1^h$ and 
$W^h = \left\{ w(\rho,\phi)|w, \frac{\partial w}{\partial\rho} , \frac{\partial^2 w}{\partial\rho^2}  \in V^h, \forall\rho < 0 \right\}.$
Next, we present the semi-discrete approximation of \eqref{v-d-problem} as
\begin{equation} \label{n-v-d-problem}
\begin{aligned}
& \text{determine } u^h\in W^h, \text{ s.t. }\forall v^h\in V^h,-\infty <\rho<0, \\
& \frac{d^2A_2(u^h,v^h)}{d\rho^2}+\frac{dA_1(u^h,v^h)}{d\rho}+A_0(u^h,v^h)=0,  \\
&  u^h(-\infty,\phi) < \infty, \quad u^h(0,\phi)=f^h(\phi),
\end{aligned}
\end{equation}
with $f^h(\phi) \in V^h$ s.t. $f^h(\phi_j) = f(\phi_j)$ for $j = 1, \ldots, M$. 
Denote the basis functions of $V_1^h$ be $\{BF_j(\phi)\}^M_{j=1}$ s.t. $BF_j(\phi_k)=\delta_{kj}, 1\leq k,j\leq M$ and
\[
BF(\phi)=\left(
\begin{matrix}
BF_1(\phi) & BF_2(\phi) &... & BF_M(\phi) & 0 & 0&...& 0\\
0 & 0&...&0  & BF_1(\phi) & BF_2(\phi) &... & BF_M(\phi)
\end{matrix}\right)^T.
\]
Let the semi-analytical solution be
\begin{equation} \label{semi approximation of the solution}
u^h(\rho,\phi)=BF^T(\phi)U(\rho).
\end{equation}
If
$
F=(f_1(\phi_1),...,f_1(\phi_M),f_2(\phi_1),...,f_2(\phi_M))^T,
$
then
$
f^h(\phi)=BF^T(\phi)F.
$
Therefore, \eqref{n-v-d-problem} reduces to the following second-order ODEs
\begin{equation} \label{eq:odes}
\begin{aligned}
& B_2U''(\rho)+B_1U'(\rho)+B_0U(\rho)=0,\quad \forall\rho\in(-\infty,0), \\
& U(-\infty) < \infty,\quad U(0)=F, 
\end{aligned}
\end{equation}
with
\begin{gather}
B_0 = -\sum_{k=1}^K \int_{\theta_k}^{\theta_{k+1}} BF'(\phi)\Psi_0^k BF'(\phi)^T d\phi,\\
B_1 = \sum_{k=1}^K \int_{\theta_k}^{\theta_{k+1}} \left( BF(\phi) \Psi_1^k BF'(\phi)^T - BF'(\phi) (\Psi_1^k)^T BF(\phi)^T \right) d\phi,\\
B_2 = \sum_{k=1}^K \int_{\theta_k}^{\theta_{k+1}} BF(\phi) \Psi_2^k BF(\phi)^T d\phi,
\end{gather}
where $BF'(\phi)$ be the derivative of $BF(\phi)$.  Then 
\begin{lemma} \label{lem: properties of B}
The constant matrix $B_2$ exhibits symmetric positive definiteness, whereas constant matrix $B_1$ demonstrates antisymmetry and constant matrix $B_0$ possesses symmetric negative semi-definite characteristics.
\end{lemma}
Which derived from  Lemma \ref{lem:A}.

We employ a direct method to solve the system of ODEs \eqref{eq:odes}. Let
\begin{equation} \label{form of U}
U(\rho)=e^{\rho\gamma}\xi,
\end{equation}
with $\gamma$ being an unknown constant and $\xi\in C^{2M}$ an unknown vector function. By inserting the solution form \eqref{form of U} into the ODEs \eqref{eq:odes}, we derive the quadratic eigenvalue problem
\begin{equation}
[\gamma^2B_2+\gamma B_1+B_0]\xi=0.
\label{eq:eig-pro}
\end{equation}
By introducing the auxiliary variable $\zeta=\gamma\xi$, an  linear generalized eigenvalue problem equivalent  to \eqref{eq:eig-pro} yields
\begin{equation}
\left(
\begin{matrix}
0 & I_{2M}\\
-B_0 & -B_1
\end{matrix}\right)\left(
\begin{matrix}
\xi\\
\zeta
\end{matrix}\right)=\gamma\left(
\begin{matrix}
I_{2M} & 0\\
0 & B_2
\end{matrix}\right)\left(
\begin{matrix}
\xi\\
\zeta
\end{matrix}\right),
\label{eq:general-eig}
\end{equation}
where $I_{2M}$ is the identity matrix. Combine the general theory of quadratic eigenvalue problems developed in \cite{quadratic-eig} with Lemma \ref{lem: properties of B}, we derive
\begin{lemma}
The generalized eigenvalue problem (\ref{eq:general-eig}) possesses exactly $2M$ eigenvalues with $Re(\gamma)\geq 0$ and $2M$ eigenvalues with $Re(\gamma)\leq 0$, counting multiplicities.
\end{lemma}

For the generalized eigenvalue problem \eqref{eq:general-eig}, numerical computation gives $2M$ eigenvalues $\{\gamma_j^h\}^{2M}_{j=1}$ with $Re(\gamma_j^h)\geq 0$ and corresponding eigenvectors $(\xi_j^T, \zeta_j^T)^T$, $j = 1, \ldots, 2M$.
The problem admits at least two zero eigenvalues, which we denote as $\gamma_1^h = \gamma_2^h = 0$. Let $\{\gamma_j^h\}_{j=1}^{2m}$ be the real eigenvalues (ordered ascendingly) and $\{\gamma_j^h\}_{j=2m+1}^{2M}$ be the complex eigenvalues with $Im(\gamma_j^h)\neq 0$, satisfying $\gamma_{2j}^h = \overline \gamma_{2j-1}^h,\, m+1 \leq j \leq M$. Hence
\begin{equation}\label{eq:U}
U(\rho) = \sum_{j=1}^{2m} \alpha_j e^{\rho \gamma_j^h} \xi_j + \sum_{j = 1+m}^{M} \left( \alpha_{2j-1} \textbf{Re} (e^{\rho\gamma_{2j}^h} \xi_{2j}) + \alpha_{2j} \textbf{Im} (e^{\rho\gamma_{2j}^h} \xi_{2j}) \right).
\end{equation}
 Since $U(0)=F$, we obtain
\begin{equation} \label{eq:F}
F = \sum_{j=1}^{2m} \alpha_j \xi_j + \sum_{j=1+m}^{M} \left( \alpha_{2j-1} \textbf{Re}(\xi_{2j}) + \alpha_{2j} \textbf{Im}(\xi_{2j}) \right).
\end{equation}
Let
$$
\begin{aligned}
EI(\rho) = [ & e^{\rho\gamma_1^h}\xi_1 , \ldots, e^{\rho\gamma_{2m}^h} \xi_{2m}, \textbf{Re}(e^{\rho\gamma_{2m+2}^h}\xi_{2m+2}), \textbf{Im}(e^{\rho\gamma_{2m+2}}\xi_{2m+2}), \ldots, \\
& \textbf{Re}(e^{\rho\gamma_{2M}^h}\xi_{2M}), \textbf{Im}(e^{\rho\gamma_{2M}^h}\xi_{2M})],
\end{aligned}
$$
$$
EI(0)=[\xi_1,...,\xi_{2m}, \textbf{Re}(\xi_{2m+2}), \textbf{Im}(\xi_{2m+2}), \ldots, \textbf{Re}(\xi_{2M}), \textbf{Im}(\xi_{2M})],
$$
$$
\alpha = [\alpha_1, \alpha_2, \ldots, \alpha_{2M}]^T.
$$
Equation (\ref{eq:F}) yields
\begin{equation}\label{eq:BB}
\alpha = EI(0)^{-1}F.
\end{equation}
Inserting (\ref{eq:BB}) into (\ref{eq:U}) gives
\begin{equation}
U(\rho) = EI(\rho) EI(0)^{-1} F.
\end{equation}
The variational problem \eqref{v-d-problem} admits a semi-discrete solution through the approximation scheme \eqref{semi approximation of the solution}, giving
\begin{equation}\label{semi-dis-solution}
u^h(\rho,\phi) = BF(\phi)^T EI(\rho) EI(0)^{-1} F.
\end{equation}

For clarity in demonstrating how our method captures solution singularities, we first consider the case where all eigenvalues $\{\gamma_j^h\}^{2M}_{j=1}$ of the quadratic eigenvalue problem \eqref{eq:eig-pro} are real. The extension to cases with complex eigenvalues follows analogous arguments. From the semi-discrete formulation \eqref{semi-dis-solution}, our numerical solution is
$
u^h = \sum_{j = 1}^{2M} \alpha_j r^{\gamma^h_j} (\Phi^h_j(\phi), \Psi^h_j(\phi))^T
$
in the polar coordinate, with
$$
\Phi^h_j(\phi) = \left( \tilde{r}(\phi) \right)^{-\gamma^h_j} \sum_{i = 1}^M BF_k(\phi) (\xi_j)_i, \quad \Psi^h_j(\phi) = \left( \tilde{r}(\phi) \right)^{-\gamma^h_j} \sum_{i = 1}^M BF_k(\phi) (\xi_j)_{M + i}.
$$
Our numerical experiments show fast convergence of $\gamma^h_j$ to the elliptic operator's true eigenvalue $b_j$, indicating that the method naturally handles singularities—refer to Section \ref{subsec: numerical examples of forward problems}. Let $u$ be the solution to \eqref{composite-eq}. The error estimate can be derived using arguments analogous to those in Theorem 4.1 of \cite{com-material}.
\begin{thm}\label{thm-error}
If $V_1^h$ consists of linear elements, then there exists $C > 0$ independent of the mesh size $h$ for which
\begin{equation} \label{eq: error estimate}
\|u-u^h\|^2_*\leq Ch^2\sum_{j=1}^2\iint_{\Omega} ( |\nabla u_j|^2+\sum_{\beta_1+\beta_2=2}(x^2+y^2)|\frac{\partial^{2} u_j}{\partial x^{\beta_1} \partial y^{\beta_2}}|^2 ) dxdy.
\end{equation}
where
\begin{gather}
\|v\|_* = E(v,v)^{1/2} + |\psi_1(v)| + |\psi_2(v)| + |\psi_3(v)|, \notag\\
\psi_1(v) = \int_{\Gamma}v_1ds,\quad
\psi_2(v) = \int_{\Gamma}v_2ds,\quad
\psi_3(v) = \int_{\Gamma}(v_1y-v_2x)ds,\notag
\end{gather}

$$
\begin{aligned}
E(w,v) & = \iint_{\Omega} \bigg( a_{11}\frac{\partial w_1}{\partial x} \frac{\partial v_1}{\partial x}+a_{22}\frac{\partial w_2}{\partial y}\frac{\partial v_2}{\partial y}+a_{33}(\frac{\partial w_1}{\partial y}+\frac{\partial w_2}{\partial x})(\frac{\partial v_1}{\partial y}+\frac{\partial v_2}{\partial x}) \\
&+a_{12}\frac{\partial w_1}{\partial x}\frac{\partial v_2}{\partial y}+a_{21}\frac{\partial v_1}{\partial x}\frac{\partial w_2}{\partial y}+ a_{13}\frac{\partial w_1}{\partial x}(\frac{\partial v_2}{\partial x}+\frac{\partial v_1}{\partial y})+a_{31}\frac{\partial v_1}{\partial x}(\frac{\partial w_2}{\partial x}+\frac{\partial w_1}{\partial y})\\
&+a_{23}\frac{\partial w_2}{\partial y}(\frac{\partial v_2}{\partial x}+\frac{\partial v_1}{\partial y}) +a_{32}\frac{\partial v_2}{\partial y}(\frac{\partial w_2}{\partial x}+\frac{\partial w_1}{\partial y}) \bigg) dxdy.
\end{aligned}
$$
\end{thm}

Observe that while the solution $u$ belongs to $H^1(\Omega)$, it does not possess  $H^2(\Omega)$-regularity. As a result, $|\nabla u|^2$ is finite, but $|D^{\beta} u|^2$ diverges for all second-order derivatives. However, the weighted term $r^2 |D^{\beta} u|^2$ is integrable because $u$ develops singularities solely along the radial direction at the origin, with asymptotic structure $\mathcal{O}(r^{b_j})$ for $0 < \textbf{Re}(b_j) < 1$. Theorem \ref{thm-error} thus guarantees that the right-hand side of \eqref{eq: error estimate} is finite, yielding first-order accuracy with respect to the $|| \cdot ||_{*}$-norm, even when $u$ lacks $H^2(\Omega)$-regularity. Combined with the symmetric positive definiteness of $a$, we derive the 
$H^1$-error control $|| u - u^h ||_{H^1} \le C || u - u^h ||_{*}$ with $C$ independent of discretization parameters. Consequently, when the tensor $a$ is symmetric positive definite, linear partial discrete approximation achieves first-order $H^1$-norm accuracy, as proved in Theorem \ref{thm-error}. This result naturally extends to quadratic elements achieve second-order convergence, with numerical confirmation provided in Example \ref{ex2}.

\section{Numerical examples} \label{sec:example}

\subsection{The forward problems} \label{subsec: numerical examples of forward problems}
In Example \ref{ex2}, we conduct a direct comparison between linear and quadratic elements for semi-discretization, employing a known exact solution for verification. And in Examples \ref{ex1}, we generate numerical solutions and approximate eigenvalues using linear elements, while establishing reference values through high-resolution computations with quadratic elements. We measure errors using the relative $H^1$-norm $\frac{||u-u^h||_{1}}{||u||_{1}}$.

\begin{example}\label{ex2} We parameterize the boundary as
$$
\tilde{r}(\phi) =
\begin{cases}
- \frac{1}{\sin(\phi)+\cos(\phi)}, & \quad  -\pi \le \phi \le -\pi/2,\\
\frac1{ \sin^4(\phi)+\cos^4(\phi)}, & \quad  -\pi/2 < \phi \le \pi/2,\\
- \frac{1}{-\sin(\phi)+\cos(\phi)}, & \quad \pi/2 < \phi \le \pi.
\end{cases}
$$
In Figure \ref{fig:domianExp2}, all points $(r,\phi)$ with $r\in(0, \tilde{r}(\phi))$ and $\phi\in(-\pi,\pi)$ comprise $\Omega$, boundary points with $\phi = -\pi, \pi$ compose $\Gamma_N$ and other boundary points constitute $\Gamma_D$.
\begin{equation} \label{equatioin of ex2}
\begin{aligned}
-\nabla\cdot \sigma & = 0,\quad u|_{\Gamma_D} & = f, \quad\sigma \cdot n|_{\Gamma_N} & = 0,
\end{aligned}
\end{equation}
with anisotropic coefficient tensor $a=\left(
\begin{matrix}
4.8 & 2.1 & 0.3\\
2.1 & 3.3 & 0.2\\
0.3 & 0.2 & 1.2
\end{matrix}\right)$.
 Let $b=a^{-1}$ and $\mu_1,\mu_2$ are the different complex roots of the equation
$$
b_{11}\mu^4-2b_{31}\mu^3+(2b_{21}+b_{33})\mu^2-2b_{32}\mu+b_{22}=0,
$$
$$
p_j=b_{11}\mu_j^2+b_{21}-b_{31}\mu_j,\quad q_j=b_{21}\mu_j+\frac{b_{22}}{\mu_j}-b_{32},\quad j=1,2.
$$
Then the exact solution\cite{Steigemann2015} of \eqref{equatioin of ex2} in the polar coordinate is
$$
\sqrt{\frac{2r}{\pi}}Re
\left(\frac1{\mu_1-\mu_2}(\mu_1\sqrt{\cos(\phi)+\mu_2\sin(\phi)}\left(
\begin{aligned}
p_2\\
q_2
\end{aligned}
\right)-\mu_2\sqrt{\cos(\phi)+\mu_1\sin(\phi)}\left(
\begin{aligned}
p_1\\
q_1
\end{aligned}
\right) )\right)
$$
