\subsection{Formal Analysis of Decentralization Metrics}
We demonstrate how the SRSW and LSW models improve decentralization over the linear stake-weight model using established metrics.

\vspace{-4pt}
\begin{lemma}
\label{lemma:nakamoto-srsw}
Given a validator set \( N \), the SRSW model's Nakamoto coefficients, for liveness \( \rho_{\mathbb{N}_L}^* \) and safety \( \rho_{\mathbb{N}_S}^* \), are greater than or equal to that of the linear stake-weight model, represented as \( \rho_{\mathbb{N}_L} \) and \( \rho_{\mathbb{N}_S} \), respectively.
\end{lemma}

\begin{proof}
Consider the Nakamoto coefficient for liveness computation in linear stake weight, let $K$ be the smallest subset such that: 
\vspace{-2pt}
\begin{equation}
    \sum_{n_i\in K} s_i > \frac{1}{3} \sum_{n_i\in N} s_i
\end{equation}
Similary in the SRSW model, let $K^*$ be the smallest subset satisfying the condition:
\vspace{-4pt}
\begin{equation}
    \sum_{i \in K^*} \sqrt{s_i} > \frac{1}{3} \sum_{i\in N} \sqrt{s_i}
\end{equation}
The concave nature of the square root function, as per Jensen's inequality~\cite{abramovich2004refining}, necessitates a larger $K^*$ to fulfill this condition in the SRSW model compared to $K$ in the linear model, thereby implying:
\vspace{-6pt}
\begin{equation}
    |K^*| \geq |K| \implies N_L^* \geq N_L
\end{equation}
\begin{equation}
    \frac{N_L^*}{m} \geq  \frac{N_L}{m} \implies \rho_{\mathbb{N}_L}^* \geq \rho_{\mathbb{N}_L}
\end{equation}
Hence, the Nakamoto coefficient for liveness is higher for SRSW compared to linear model. Similarly, we can prove for Nakamoto coefficient-safety, i.e., $\rho_{\mathbb{N}_S}^* \geq \rho_{\mathbb{N}_S}$. 
\end{proof}

\begin{lemma}
\label{lemma:srsw-gini}
Given \( N \), the Gini of SRSW and linear models, represented by \( G^* \) and \( G \), respectively, satisfy \( G^* \leq G \).
\end{lemma}

\begin{proof}
This proof draws upon the established principles from Lemma~\ref{lemma:nakamoto-srsw} and the definitions provided in Section~\ref{sec:metrics}.

In the SRSW model, the square root transformation applied to validator stakes results in a more uniform distribution of weights, effectively reducing relative disparities in stake sizes compared to the linear model. Consequently, this leads to a lower Gini index in the SRSW model, compared to the Gini index in the linear model.

Therefore, \( G^* \leq G \), indicating a more equitable distribution of validator influence under the SRSW model.
\end{proof}
\vspace{-5pt}


\begin{theorem}
\label{theorem:srsw-good}
Given a validator set \( N \), the SRSW model achieves a degree of decentralization, across key metrics, that is greater than or equal to that of the linear stake-weight model.
\end{theorem}


\begin{proof}
Building on Lemma~\ref{lemma:nakamoto-srsw} and Lemma~\ref{lemma:srsw-gini}, the concave nature of the SRSW model reduces influence concentration by limiting large validators' dominance, resulting in lower HHI and Gini values. Additionally, due to its correlation with weights, the Shapley value distribution enhances decentralization. The Zipf’s coefficient also decreases, reflecting a balanced distribution among validators. Thus, across all metrics, the SRSW model achieves higher degree of decentralization compared to the linear model.
\end{proof}


\begin{theorem}
\label{theorem:lsw-superior}
Given a validator set \( N \), the LSW model achieves a higher degree of decentralization across key metrics than the SRSW model.
\end{theorem}

\begin{proof}
Let \( K^* \) be the smallest subset of validators in SRSW satisfying:
\begin{equation}
    \sum_{n_i \in K^*} \sqrt{s_i} > \frac{1}{3} \sum_{n_i \in N} \sqrt{s_i}.
\end{equation}
For LSW, let \( K^{\phi} \) be the smallest subset satisfying:
\begin{equation}
    \sum_{n_i \in K^{\phi}} \log(s_i) > \frac{1}{3} \sum_{n_i \in N} \log(s_i).
\end{equation}
Since \( \log(s) \) is more concave than \( \sqrt{s} \), Jensen’s inequality~\cite{abramovich2004refining} implies that a larger subset \( K^{\phi} \) is required for LSW to meet this threshold, yielding:
\begin{equation}
    |K^{\phi}| \geq |K^*| \implies \rho_{\mathbb{N}_L}^{\phi} \geq \rho_{\mathbb{N}_L}^*.
\end{equation}

This advantage extends to the Nakamoto coefficient for safety, as well as other decentralization metrics, including Gini, HHI, Shapley values, and Zipf's coefficient. Thus, the LSW model achieves a higher degree of decentralization than the SRSW model.
\end{proof}

\begin{corollary}
\label{corollary:lsw-linear}
By Theorem~\ref{theorem:srsw-good} and Theorem~\ref{theorem:lsw-superior}, and using transitivity, the LSW model achieves a higher degree of decentralization than the linear stake-weight model across all metrics.
\end{corollary}
