\subsection{Proof of Proposition \ref{prop1}}




 First, we derive the optimization objectives with independent learning framework. By decomposing the KL term in (\ref{ind_loss}), we have
    \begin{equation*}
    \mathcal{L}_{Ind} = \sum_{i=1}^n \left( \mathbb{E}_{s \sim \mathcal{D}_{\mu}, a_i \sim \pi_{\theta_i}}  Q^i(s, a_i)  + \frac{1}{\beta} \mathbb{E}_{s \sim \mathcal{D}^\mu, a_i \sim \pi_{\theta_i}}  \log \mu_i(a_i|s)  + \frac{1}{\beta} \mathbb{E}_{s \sim \mathcal{D}^\mu}  \mathcal{H}(\pi_i(a_i|s))  \right)
\end{equation*}
where $\mathcal{H}(\pi_i(a_i|s))$ is the entropy of the agent $i$'s policy. As BRPO-Ind learns behavior policy independently, we can directly get the term $\log \mu_i(a_i|s)$ implicitly from the pretrained diffusion models of each agent.

Consider that each agent's policy is trained independently without dependency, we can derive  the gradient of agent $i$ as 
\begin{align}
   \nonumber \nabla_{\theta_i} \mathcal{L}_{Ind} & =  \nabla_{\theta_i} \sum_{i=1}^n \left( \mathbb{E}_{s \sim \mathcal{D}_{\mu}, a_i \sim \pi_{\theta_i}}  Q^i(s, a_i)  + \frac{1}{\beta} \mathbb{E}_{s \sim \mathcal{D}^\mu, a_i \sim \pi_{\theta_i}}  \log \mu_i(a_i|s)  + \frac{1}{\beta} \mathbb{E}_{s \sim \mathcal{D}^\mu}  \mathcal{H}(\pi_i(a_i|s))  \right) \\
  \nonumber  & = \mathbb{E}_{s \sim \mathcal{D}_{\mu}, a_i \sim \pi_{\theta_i}} \left[  \nabla_{\theta_i} Q^i(s, a_i) + \frac{1}{\beta} \nabla_{\theta_i} \log\mu_i(a_i|s)     \right] \\
 \nonumber   & = \mathbb{E}_{s \sim \mathcal{D}^\mu, a_i \sim \pi_{\theta_i}} \left[  \nabla_{\theta_i} \pi_i * \nabla_{a_i} Q^i(s, a_i) + \frac{1}{\beta} \nabla_{\theta_i} \pi_i * \nabla_{a_i} \log\mu_i(a_i|s)     \right] \\
  \nonumber  & = \mathbb{E}_{s \sim \mathcal{D}^\mu, a_i \sim \pi_{\theta_i}} \left[ \nabla_{a_i} Q^i(s, a_i) + \frac{1}{\beta}  \nabla_{a_i} \log\mu_i(a_i|s)     \right] \nabla_{\theta_i} \pi_i  .
\end{align}


Notice that the term $ \nabla_{a_i} \log\mu_i(a_i|s)$ serves as the score function of the independent behavior policy, we can further construct a surrogate loss $\mathcal{L}_{Ind}^{surr}$ and derive a practical gradient for BRPO-Ind.  Our proof is mainly inspired by the following Lemma \ref{chen_lemma}. 
\begin{lemma}[Proposition 1 in \cite{chen2024score}]\label{chen_lemma}
Given that $\pi$ is sufficiently expressive, for any time $t$, any state $s$, we have
\begin{equation*}
\arg\min_{\pi} D_{\text{KL}}  [\pi_t(\cdot|s)||\mu_t(\cdot|s)] = \arg\min_{\pi} D_{\text{KL}}  [\pi(\cdot|s)||\mu(\cdot|s)],
\end{equation*}
where both $\mu_t$ and $\pi_t$ follow the same predefined diffusion process in $q_{t_0}(x_t|x_0) = \mathcal{N}(x_t|\alpha_t x_0, \sigma_t^2 I)$, which implies $ x_t = \alpha_t x_0 + \sigma_t \varepsilon$.
\end{lemma}

The surrogate loss is 
\begin{equation}\label{ind_surr}
    L_{Ind}^\text{surr} (\theta_i) = \mathbb{E}_{s,a_i \sim \pi_{\theta_i}} Q(s, a_i) - \frac{1}{\beta} \mathbb{E}_{t,s} \omega(t) \frac{\sigma_t}{ \alpha_t} D_{\text{KL}} [\pi_{\theta_i, t}(\cdot|s) \| \mu_{i,t}(\cdot|s)].
\end{equation}
Then we can propose the practical gradient as follows. 
\begin{proposition}[Practical Gradient of BRPO-Ind] Given that $\pi_{\theta_i}$ is deterministic policy and $\epsilon_i^*$ is the optimal diffusion model of independent behavior policy $\mu_i$, the gradient of the surrogate loss (\ref{ind_surr}) w.r.t agent $i$ is
\begin{equation*}
    \nabla_{\theta_i} L_{\text{surr}}^\pi (\theta) = \left[ \mathbb{E}_s \nabla_a Q_\phi(s, a)|_{a=\pi_\theta(s)} - \frac{1}{\beta} \mathbb{E}_{t,s} \omega(t) (\epsilon_i^*(a_{t,i}|s, t) - \epsilon_i)|_{a_{i,t}=\alpha_t\pi_{\theta_i}(s)+\sigma_t\epsilon_i} \right] \nabla_{\theta_i} \pi_{\theta_i} (s).
\end{equation*}

\end{proposition}



