	In this section, we design reduction rules to obtain an equivalent instance of \sfastr with at most $\OO(k)$ terminal vertices. That is, $|S|\leq \OO(k)$. For a gentle introduction, we first provide a slightly worse quadratic bound on the number of terminals, and then refine it to a linear bound.


	% Our first objective is to bound the number of $S$-vertices. In this section, we establish a linear bound on the number of $S$-vertices. Prior to that, we derive a more straightforward quadratic bound. 
	\subsection{Quadratic Upper Bound on the Number of Terminals}

	The first reduction rule handles sanity checks; its correctness is self-evident. 

	\begin{reduction rule}[Sanity Check]
		\label{redrule:sanity_check}
		Let $(T,S,k)$ be an instance of \sfastr where $k \leq 0$. If $k=0$ and $T$ has no $S$-triangle, return a trivial \yes instance; otherwise, return a trivial \no instance.
	\end{reduction rule}

	To reduce the number of terminal vertices, we further remove irrelevant $S$-vertices from the graph.  The following reduction rule is designed to accomplish this task.

	\begin{reduction rule}[Irrelevant Vertex Rule 1] \label{redrule:triangle_free_vertex}
		Let $(T,S,k)$ be an instance of \sfastr. If there is a vertex $s \in S$ such that $s$ does not participate in any triangle in $T$, then delete $s$ from $T$. The resulting instance is $(T'= T - s, S \setminus \{s\}, k).$
	\end{reduction rule}

	It is easy to verify that \cref{redrule:triangle_free_vertex} can be applied in polynomial time.  In the following, we prove the correctness of it.

	\begin{lemma}
		\cref{redrule:triangle_free_vertex} is sound.
	\end{lemma}

	\begin{proof}
		The key aspect of the proof is that the sets of $S$-cycles in $T$ and $T'$ are identical.

		In the forward direction, let $(T,S,k)$ be a \yes instance of \sfastr and $F \subseteq A(T)$ be a solution of size at most $k$. Clearly, $F'= F \setminus \arc(s)$ is a solution for $(T'= T - s, S \setminus \{s\}, k)$ of size at most $k$, where $\arc(s) \subseteq A(T)$ is the  set of arcs incident to the vertex $s$ in $T$.

		% In the reverse direction, let $(T'= T - s, S \setminus \{s\}, k)$ be a \yes instance of \sfastr and $\widetilde{F} \subseteq A(T)$ be a solution of size at most $k$. We claim that, $\widetilde{F}$ is also a solution of size at most $k$ for $(T,S,k)$. Assume towards contradiction that there exists a $S$-triangle  in $T\circledast \widetilde{F}$. Since $\widetilde{F}$ was a solution for $(T', S \setminus \{s\},k)$, this implies that every $S$-triangle in $T$ \todo{why that $S$ triangle  must be in $T$}passes through the vertex $s$ which is a contradiction.

		In the reverse direction, let $(T - s, S \setminus \{s\}, k)$ be a \yes instance of \sfastr and $\widetilde{F} \subseteq A(T)$ be a minimal solution of size at most $k$. We claim that, $\widetilde{F}$ is also a solution of size at most $k$ for $(T,S,k)$. Assume towards contradiction that there exists a $S$-triangle  in $T\circledast \widetilde{F}$. Since $\widetilde{F}$ was a solution for $(T', S \setminus \{s\},k)$, the triangle must contain the vertex $s$. Let $\triangle$ be such a triangle with the vertices $\{s, p, q\}$ and arcs $\{(s,p), (p,q), (q,s)\}$. Now if $(p,q) \notin \widetilde{F}$ we obtain a $S$-triangle in $T$ with vertices $\{s,p,q\}$, a contradiction to the fact that  $s$ does not participate in any triangle in $T$. Else $(q,p) \in  \widetilde{F}$. As $\widetilde{F}$ is minimal solution there is a $S$-cycle $C$ in $T-s$,  such that  $A(C) \cap \widetilde{F} = \{(q,p)\}$. That means there is a path from $p$ to $q$ in $T$ containing the arcs $A(C) \setminus (q,p)$. As $(s,p), (q,s) \in A(T)$, we obtain  a $S$-cycle $C_1$ in $T - \widetilde{F}$ where $s \in V(C_1)$. By \cref{obs:striangle},  $T$ has a $S$-triangle containing the vertex $s$, a contradiction.
	\end{proof}
