	It is easy to verify that \cref{redrule:many_triangle} can be applied in polynomial time.  In the following, we prove the correctness of it.

	\begin{lemma}
		\cref{redrule:many_triangle} is sound.
	\end{lemma}

	\begin{proof}
		In the forward direction, let $(T,S,k)$ be a \yes instance of \sfastr and $F \subseteq A(T)$ be a solution of size at most $k$. So $T\circledast F$ does not contain any $S$-triangle. Observe that $F$ must include the arc $e$. If it does not, then to hit all the $(k+1)$ $S$-triangles that contain the arc $e$, we need to reverse at least $k+1$ arcs, which is not feasible since we are allowed to reverse at most $k$ arcs. We claim that $F'= F \setminus \{e\}$ is a solution of size at most $k-1$ for $(T'=T \circledast e, S, k-1)$.  Notice that $T\circledast F$ and $T'\circledast F'$ are the same tournaments. So, if $T'\circledast F'$ has a $S$-triangle, then that will imply that $T\circledast F$ also has a $S$-triangle which contradicts that $F$ is a solution for $(T,S,k)$. 

		In the reverse direction, let $(T'=T \circledast e, S, k-1)$ be a \yes instance of \sfastr and  $\widetilde{F}$ be a solution of size at most $k-1$. Consider $\widetilde{F}'= \widetilde{F} \cup \{e\}$. We claim that $\widetilde{F}'$ is a solution of size at most $k$ for $(T,S,k)$. 
		% Assume towards contradiction that there is a $S$-triangle in $T\circledast \widetilde{F}'$. Since, $\widetilde{F}$ was a solution for $(T',S,k-1)$, this implies that every $S$-triangle in $T\circledast \widetilde{F}'$ has the arc $e$ in it. 
		Now note that $T'\circledast \widetilde{F}$ and $T\circledast \widetilde{F}'$ are the same tournaments. So, if $T\circledast \widetilde{F}'$ has a $S$-triangle, then that will imply that $T'\circledast \widetilde{F}$ also has a $S$-triangle which contradicts that $\widetilde{F}$ is a solution for $(T',S,k-1)$. 
	\end{proof}

	\begin{reduction rule}[Bounded Terminal Rule] \label{redrule:no_instance}
		Let $(T,S,k)$ be an instance where none of the  Reduction Rules \ref{redrule:sanity_check}-\ref{redrule:many_triangle} are applicable. If $|S| \geq (k+1)^2$, then return a trivial \no instance.
	\end{reduction rule}

	It is easy to verify that \cref{redrule:no_instance} can be applied in polynomial time.  In the following, we prove the correctness of it.

	\begin{lemma}
		\cref{redrule:no_instance} is sound.
	\end{lemma}

	\begin{proof}
		Let $(T,S,k)$ be a \yes instance for \sfastr where none of the Reduction Rules \ref{redrule:sanity_check}-\ref{redrule:many_triangle} are applicable. Let $F \subseteq A(T)$ be a solution of size at most $k$. Let $V(F)$ be the set of vertices that are incident to at least one of the arcs of $F$. Clearly $|V(F)| \leq 2k$. Now, consider $V(T) \setminus V(F)$. Since \cref{redrule:triangle_free_vertex} is not applicable to $(T,S,k)$, every $S$-vertex in $V(T) \setminus V(F)$  participates in some $S$-triangle. Moreover, since $F$ is a solution, one of the arcs of that $S$-triangle must be in $F$. Since \cref{redrule:many_triangle} is not applicable to $(T,S,k)$, it follows that for every arc $e \in F$, there are at most $k$ $S$-vertices that are involved in $S$-triangles where $e$ serves as a common arc and the other arcs are disjoint. So, the number of such $S$-vertices in $V(T) \setminus V(F)$ is upper bounded by $k^2$. So, the overall number of $S$-vertices is bounded by $k^2 + 2k =  (k+1)^2 -1$. 
	\end{proof}

	Let $(T,S,k)$ be an instance where none of the Reduction Rules \ref{redrule:sanity_check}-\ref{redrule:no_instance} are applicable. This immediately bounds the number of $S$-vertices in $(T,S,k)$. We formalize it in the following Lemma.

	\begin{lemma}\label{lem:ter}
		Let $(T,S,k)$ be an instance where none of the Reduction Rules \ref{redrule:sanity_check}-\ref{redrule:no_instance} are applicable. Then the number of terminals, that is, $|S|$ is upper bounded by $(k+1)^2$.
	\end{lemma}

