	\begin{definition}[certificate of an arc]	
		{\em Consider an ordered partition $ P_{\sigma} = (V_1, \ldots, V_{\ell}) $ of an ordered tournament  $T_{\sigma}$ and let $ f = (v,u) $ be a backward arc of $T_{\sigma} $. We refer to a {\em certificate} of $f$, denoted by $ c ( f ) $, as 
			any directed    $S$-path from $ u $ to $ v $ that utilizes only forward arcs from $ A_B(T_{\sigma}, P_{\sigma}) $.}
	\end{definition}

	\begin{definition}[certification of an arc set]	
		{\em Consider an ordered partition $ P_{\sigma} = (V_1, \ldots, V_{\ell}) $ of an ordered tournament  $T_{\sigma}$  and let $ F $ be a set of some backward arcs of $T_{\sigma} $. 
			We say that	{\em we can certify} $ F $ whenever it is possible to find a set $ \FF= \{c(f) : f \in F\} $ of arc-disjoint  certificates for the arcs in $ F $.}
	\end{definition}




	\begin{definition}[safe partition]

		{\em Consider an ordered partition $ P_{\sigma} = (V_1, \ldots, V_{\ell}) $ of an ordered tournament  $T_{\sigma}$. Let $B_E$ denote the set of all backward arcs in $ A_B(T_{\sigma}, P_{\sigma}) $. For a vertex subset $S \subseteq V(T)$, we say $ P_{\sigma}$ is  a
			{\em $ S $-safe partition}  if   we can certify $B_E$. %the following holds:
			% \begin{enumerate}[(i)]
				% 	\item Each arc in $B_E$ is $S$-backward.

				% 	\item 	We can certify $B_E$.
				% \end{enumerate}
		}

	\end{definition}

	Let $D_{\sigma} = (V_{\sigma} , A)$ be an ordered directed graph. We use $\textsf{Sfas}(D_{\sigma},S) $  to denote the size of a minimum subset feedback arc set in the directed graph $D_{\sigma}$. Specifically, given a directed graph  $D_{\sigma}$, and a vertex subset $S \subseteq V_{\sigma}$, it refers to the cardinality of the smallest
	set $ F \subseteq A$ of arcs whose removal (or reversal) renders $ D_{\sigma} $ $ S $-acyclic. Given a tournament, for an arc subset $A' \subseteq A[T]$, the directed graph $T[A']$ is defined by the subgraph $T$ containing the arc set $A'$. More specifically, $T[A']= (V(T), A')$.  For a ease of notation, when the subset is clear to the context, we use $\textsf{Sfas}(D_{\sigma}) $ instead of $\textsf{Sfas}(D_{\sigma}) $.

	\begin{lemma}\label{lem:safe}
		Consider an ordered partition $ P_{\sigma} = (V_1, \ldots, V_{\ell}) $ of an ordered tournament  $T_{\sigma}$ and a terminal set $S \subseteq V(T)$. If $ P_{\sigma}$ is  a $ S $-safe partition then, 

		$$ \textsf{Sfas}(T_{\sigma}) = \textsf{Sfas}(T_{\sigma} [A_I(T_{\sigma}, P_{\sigma})])+\textsf{Sfas}(T_{\sigma} [A_B(T_{\sigma}, P_{\sigma})])$$
		Moreover, there
		exists a minimum sized $S$-feedback arc set of $ T_{\sigma} $ containing $ B_E $, where $B_E$ denote the set of all backward arcs in $ A_B(T_{\sigma}, P_{\sigma}) $.

	\end{lemma}

	\begin{proof}
		Given any bipartition of the arc set \( A \) into \( A_1 \) and \( A_2 \), we have 
		$$
		\textsf{Sfas}(T_{\sigma}) \geq \textsf{Sfas}(T_{\sigma}[A_1]) + \textsf{Sfas}(T_{\sigma}[A_2]).$$
		Specifically, for the partition of \( A \) into \( A_I(T_{\sigma}, P_{\sigma}) \) and \( A_B(T_{\sigma}, P_{\sigma}) \), it follows that 
		$$\textsf{Sfas}(T_{\sigma}) \geq \textsf{Sfas}\big(T_{\sigma}[A_I(T_{\sigma}, P_{\sigma})]\big) + \textsf{Sfas}\big(T_{\sigma}[A_B(T_{\sigma}, P_{\sigma})]\big).$$ 
		Next, we need to show that 
		$$
		\textsf{Sfas}(T_{\sigma}) \leq \textsf{Sfas}\big(T_{\sigma}[A_I(T_{\sigma}, P_{\sigma})]\big) + \textsf{Sfas}\big(T_{\sigma}[A_B(T_{\sigma}, P_{\sigma})]\big).
		$$

		This assertion holds because, after reversing all arcs in \( B_E \), each remaining directed \( S \)-cycle is contained within \( T_{\sigma}[V_i] \) for some \( i \in [\ell] \). In other words, once all arcs in \( B_E \) are reversed, every \( S \)-cycle is entirely contained within \( T_{\sigma}[A_I(T_{\sigma}, P_{\sigma})] \). Observe that as $ P_{\sigma}$ is   $ S $-safe,    the set of all backward arcs of  $A_B(T_{\sigma}, P_{\sigma})$, i.e., \( B_E \) can be certified using only arcs from $A_B(T_{\sigma}, P_{\sigma})$. This concludes the proof of the first part of the lemma. Essentially, we have shown the existence of a minimum-sized \( S \)-feedback arc set for \( T_{\sigma} \) that includes \( B_E \).  This completes the proof of the lemma.
		%\todo{Proof of why $B_E$ should be part of a minimum solution is not clear. We need to add its because each such arc can be certified}.
		% Given any bipartition of the arc set $A$ into $A_1$ and $A_2$, we have $\sfas(T_{\sigma}) \geq \sfas(T_{\sigma} [A_1] )+  \sfas(T_{\sigma} [A_2] )$. Specifically, for the partition of $A$ into $A_I(T_{\sigma}, P_{\sigma})$ and $A_B(T_{\sigma}, P_{\sigma})$, it holds that $ \sfas(T_{\sigma}) \geq  \sfas(T_{\sigma} [A_I(T_{\sigma}, P_{\sigma})])+ \sfas(T_{\sigma} [A_B(T_{\sigma}, P_{\sigma})])$. Next, we need to show that $ \sfas(T_{\sigma}) \leq  \sfas(T_{\sigma} [A_I(T_{\sigma}, P_{\sigma})])+ \sfas(T_{\sigma} [A_B(T_{\sigma}, P_{\sigma})])$. This assertion follows because, after reversing all arcs in $B_E$, each remaining directed $S$-cycle is included in $ T_{\sigma}[V_i] $ for some $i \in [\ell]$. In other words, once all arcs in $B_E$ are reversed, every $S$-cycle is completely contained within $ T_{\sigma}[A_I] $. This completes the proof of the first part of the lemma. In essence, we have demonstrated the existence of a minimum sized $S$-feedback arc set of $ T_{\sigma}$ that includes $B_E$. This completes the proof of the lemma. 
	\end{proof}

	\subparagraph{Construction of  a $\boldsymbol{S}$-safe partition.}
	Recall that an \( S \)-triangle is a directed cycle of length three that includes at least one vertex from \( S \). It is clear that the number of arc-disjoint \( S \)-triangles provides a lower bound for the size of the smallest \( S \)-feedback arc set in a tournament. We illustrate how this set can be utilized to identify a safe partition in polynomial time.

	% Recall that an $S$-triangle is a directed cycle of length three that includes at least one vertex from $S$. It is evident that the number of arc-disjoint $S$-triangles gives a lower bound for the size of the smallest $S$-feedback arc set in a tournament. We demonstrate how this set can be employed to determine a safe partition in polynomial time.

	\begin{definition}[Conflict $S$-packing]
		{\em  A {\em conflict $S$-packing} of a tournament $ T $ is a maximal collection of arc-disjoint $S$-triangles.}
	\end{definition}
	Observe that a conflict \( S \)-packing can be computed in polynomial time, for instance, by using the following \emph{greedy} algorithm: find an \( S \)-triangle, delete its arcs, and continue. Given an \( S \)-conflict packing \( \mathcal{C} \) of an instance \( (T, S, k) \) of \sfastr, let \( V(\mathcal{C}) \) denote the set of vertices covered by \( \mathcal{C} \), and \( A(\mathcal{C}) \) denote the set of all arcs contained in \( \mathcal{C} \). See \Cref{fig:partition2} for an illustration of conflict \( S \)-packing. The following observation is immediate.

	\begin{observation}\label{obs:cfno}
		Let $ \CC $ be a conflict $ S $-packing of a tournament $ T $. If $ (T,S,k) $ is an \yes instance of  \sfastr, then $ |\CC| \leq   k $ and $ |V (\CC)| \leq   3k $.

	\end{observation}

