\begin{lemma}[Arc Swapping Lemma]\label{lem:swapping_lemma}
	Let $z \notin Z_{\relevant}$ be any non-$S$ vertex such that there exist two vertices $p,q \in Z_{\relevant}$ such that $P= \{(z,p), (q,z)\} \subseteq  A(T)$  then $(T, S, k)$ is a {\em \yes} instance if and only if $(T'= T\circledast P, S, k)$ is a {\em \yes} instance. 
\end{lemma}

\begin{proof}
	In the forward direction, let $(T, S, k)$ be a \yes instance and let $F$ be a minimal solution of size at most $k$. Now we make a case distinction as follows.

	\begin{description}
		\item[Case 1: $(z,p),~(q,z) \in F$:\label{case31}]  In this case, we will show that $F'= F \setminus P$ is a solution of size at most $k-2$ for $(T', S, k)$. Notice that $T\circledast F$ and $T'\circledast F'$ are the same tournaments. So, if $T'\circledast F'$ has a $S$-triangle, then that will imply that $T\circledast F$ also has a $S$-triangle which contradicts that $F$ is a solution for $(T,S,k)$. 

		%\medskip 

		\item[Case 2: $(z,p) \in F,~(q,z) \notin F$:\label{case32}] We only consider this case since the case $(z,p) \notin F,~(q,z) \in F$ is symmetric. Consider $F'= F \setminus (z,p) \cup \rev(q,z)$. We claim that $F'$ is a solution of size at most $k$ for $(T', S, k)$.  Notice that the tournaments $T\circledast F$ and $T'\circledast F'$ are the same tournaments. Hence it directly follows that any $S$-triangle in $T'\circledast F'$ will directly imply having the same $S$-triangle in $T\circledast F$ which contradicts that $F$ is a solution for $(T,S,k)$.

		% \medskip 

		\item[Case 3: $(z,p) \notin F,~(q,z) \notin F$:\label{case34}] In this case, we claim that $F$ is also a solution of size at most $k$ for $(T',S,k)$. Suppose not, this implies that $T'\circledast F$ has a $S$ triangle, $\triangle$. Since $T\circledast F$ did not have any $S$-triangle, this implies that $\triangle$ must contain at least one of the arcs $(p,z)$ and $(z,q)$ (reversed arcs corresponding to $(z,p)$ and $(q,z)$, respectively). Without loss of generality assume that $(p,z) \in \triangle$ (proof for the case when  $(z,q) \in \triangle$ is identical).

		\begin{description}\item[When $(p,z) \in \triangle$: \label{subcase1}] 
			Since $z,p \notin S$, let the third vertex of $\triangle$ be $s \in S$ and the arcs of $\triangle$ be $(p,z),(z,s)$ and $(s,p)$. Since $|Z| > 7k+4$ and $p \in Z_{\relevant} \subseteq Z'$, the arc $(s,p)$ is a \surearc in $(T,S,k)$ (by \cref{obs:sure_arc2}). Moreover since $p \in Z'$ and for every $s' \in S_2$, the arc $(p,s')$ is a \surearc in $(T,S,k)$ (by \cref{obs:sure_arc2}), this implies that $s \notin S_2$. So we assume that $s \in S_1$. Now consider $T\circledast F$. Since $q \in Z'$, the arc $(s,q)$ is also a \surearc in $(T,S,k)$ (by \cref{obs:sure_arc2}) and hence $F$ avoids this arc in the instance $(T,S,k)$. $T\circledast F$ has the arc $(q,z)$ since $(q,z) \notin F$. Consider the arc $(z,s)$. If $(z,s) \notin F$, then we found a triangle $(s,q),(q,z)$ and $(z,s)$ in $T\circledast F$ which contradicts that $F$ is a solution for $(T,S,k)$. Let's assume that $(z,s) \in F$. Since $F$ is a minimal solution, there must exist a  cycle $C$ such that $\arc(C) \cap F = \{(z,s)\}$. Now, consider a closed walk \( W \) that traces the triangle formed by the arcs \( (s,q), (q,z), \) and \( (z,s) \). The arcs \( (s,q) \) and \( (q,z) \) remain the same in $W$, but instead of following the arc \( (z,s) \), we traverse the path \( C - (z,s) \) from the corresponding cycle of \( (z,s) \). By definition, \( W \) is a closed walk, and notably, it contains the vertex \( s \in S_1 \) while avoiding all arcs from \( F \). From this, we can easily extract a cycle that includes \( s \), and by \cref{lem:Scycle}, we find a triangle containing \( s \) that avoids all arcs of \( F \), leading to a contradiction.    
			% {\color{red}Now consider a closed walk $W$ that follows along the triangle with arcs $(s,q),(q,z)$ and $(z,s)$. The arcs $(s,q)$ and $(q,z)$ remains the same and when the arc $(z,s)$ comes, then instead of following that arc, we follow the path $C - (z,s)$ from the corresponding cycle of $(z,s)$. By definition, $W$ is a closed walk and moreover it does not contain any arc of $F$ and contains the vertex $s \in S_1$. From here we can easily retrieve a cycle containing $s$ and hence by \cref{lem:Scycle}, we find a triangle containing $s$ that avoids any arc of $F$ which leads to a contradiction.}
			% \medskip 
			% \item[Subcase 2: $(z,q) \in \triangle$:] Argument for this case is similar as  for \hyperref[subcase1]{Subcase 1}. 
		\end{description}
	\end{description}
	In the reverse direction, note that we apply the same operation on the instance $(T', S, k)$ to transform it back to $(T, S, k)$. Thus, the proof for the reverse direction mirrors the proof for the forward direction.
	% In the reverse direction, observe that we perform the same operation on the instance $(T',S,k)$ to reach to the instance $(T,S,k)$. So the proof for the reverse direction is exactly same as the proof for the forward direction.
\end{proof}


The next lemma utilizes the Arc Swapping Lemma (\Cref{lem:swapping_lemma}) to reduce the size of \(Z_{\relevant}\) to \(2k+2\). 



\begin{lemma}\label{lem-upper-bound-relevant}
	Given an instance $(T,S,k)$ of \sfastr, in polynomial time we can obtain an instance $(T',S,k)$ such that 
	$(T,S,k)$ is a \yes instance if and only if $(T',S,k)$ is a \yes instance. Moreover, in $T'$, the size of $Z_{\relevant}$ is upper bounded by $2k+2$.
\end{lemma}
\begin{proof}
	We assume that the size of \(Z_{\relevant}\) is at least \(2k+2\); otherwise, the proof is already complete.  
	We partition \( Z_{\relevant} \) into two parts, \( Z_{\relevant}^1 \uplus Z_{\relevant}^2 \), where \( Z_{\relevant}^1 = \INN_{Z'}(\widetilde{Z}_-) \cup \INN_{Z'}(R_<) \) and \( Z_{\relevant}^2 = \OUTT_{Z'}(\widetilde{Z}_+) \cup \OUTT_{Z'}(R_>) \). We will first provide an upper bound for the size of the set \( Z_{\relevant}^1 \), and the argument for bounding the size of \( Z_{\relevant}^2 \) is symmetric. The proof utilizes Lemma~\ref{lem:swapping_lemma}, applied to a specific subset of \( Z_{\relevant}^1 \).

	We order the vertices in \( Z_{\relevant}^1 \) arbitrarily. Let \( Z_{\relevant}^1[k+1] \) denote the first \( k+1 \) vertices in that order. Now, consider the set \( \widetilde{Z}_- \cup R_< \), which contains vertices with in-degree at most \( k \) in \( Z' \). For each vertex \( v \in \widetilde{Z}_- \cup R_< \), proceed as follows: choose an in-neighbor \( u \) of \( v \) in \( Z_{\relevant}^1 \setminus Z_{\relevant}^1 [k+1] \). Since the number of in-neighbors of \( v \) in \( Z' \) is at most \( k \), there must be a vertex \( w \in Z_{\relevant}^1[k+1] \) such that \( w \) is an out-neighbor of \( v \). Given that \( u \) is an in-neighbor and \( w \) is an out-neighbor of \( v \), we can apply \cref{lem:swapping_lemma} to obtain an equivalent instance \( (T' = T - \{(u,v),(v,w)\} + \{(v,u),(w,v)\}, S, k) \). 

	We continue applying \cref{lem:swapping_lemma} for each vertex \( v \) until \( v \) has no remaining in-neighbors in \( Z_{\relevant}^1 \setminus Z_{\relevant}^1 [k+1] \). Then, we move to the next vertex in \( \widetilde{Z}_- \cup R_< \). The proof of the correctness of this step follows by induction on the number of swapped arcs and from the correctness of the lemma \cref{lem:swapping_lemma}. Once this process is applied exhaustively to every vertex in \( \widetilde{Z}_- \cup R_< \), the arcs in \( A(\widetilde{Z}_- \cup R_<, Z_{\relevant}^1 \setminus Z_{\relevant}^1 [k+1]) \) will all originate from \( \widetilde{Z}_- \cup R_< \) and terminate in \( Z_{\relevant}^1 \setminus Z_{\relevant}^1 [k] \). Furthermore, all the in-neighbors of \( \widetilde{Z}_- \cup R_< \) within \( Z' \) will belong to \( Z_{\relevant}^1 [k+1] \), i.e., \( \INN_{Z'}(\widetilde{Z}_-) \cup \INN_{Z'}(R_<) \subseteq Z_{\relevant}^1 [k+1] \). Since \( Z_{\relevant}^1 [k+1] \) has size \( k+1 \), the size of \( Z_{\relevant}^1 = \INN_{Z'}(\widetilde{Z}_-) \cup \INN_{Z'}(R_<) \) is also bounded by \( k+1 \).

	Similarly, the size of \( Z_{\relevant}^2 \) is also bounded above by \( k+1 \). Therefore, the total size of \( Z_{\relevant} \) is at most \( 2k+2 \). This completes the proof.
\end{proof}

