% \end{proof} 

Let $S_i=V_i \cap S$. Due to \Cref{obs:color1}, the vertices $V_i$ has a unique $\spclorderi$ -- we refer this ordering as $\sigma_i$. 

\begin{observation}\label{obs:color2}
For every color class $V_i$ of $T$, let $s_i^1, s_i^2, \ldots, s_i^{n_i}$ be the order in
which the vertices of $S_i$ appear according to $\sigma_i$. If $F$ is a colorful solution and $\sigma$ is the unique $\spclorder$ of  $T \circledast F $ then
\begin{enumerate}[(i)]
	\item For each $j \in [n_i -1]$, $s_i^j <_{\sigma} s_i^{j+1}$
	\item For each non $S$-vertex $v$ in $V_i$, $s_i^j <_{\sigma_i} v <_{\sigma_i}  s_i^{j+1} \implies s_i^j <_{\sigma} v <_{\sigma}  s_i^{j+1}$
\end{enumerate}
\end{observation}

\subparagraph{Modification of the instance.}

We modify the instance $ (T,S,k,q) $ of \csfast to $ (T',S,k,q) $ of the same problem as follows.
\begin{enumerate}
\item For each $ i \in [q] $, we partition the graph $ T[V_i] $ into a set of maximal \scc's.

\item We construct a new tournament  $ T' $ as follows. Let $\mathcal{C}_i$ denote the set of all maximal \scc's in $T[V_i]$ and  $\mathcal{C}\coloneqq \bigcup_{i \in [q]} \mathcal{C}_i$.
\begin{itemize}
	\item  Each \scc $ C $ in $ \mathcal{C} $ corresponds to a vertex $ v_C $ in $ T'$. 
	\item For each pair of vertices $u \in V(C_1)$ and $v \in V(C_2)$ for some $C_1, C_2 \in \mathcal{C}$, $C_1 \neq C_2$  with $(u,v) \in A(T)$, we add an arc $ (v_{C_1}, v_{C_2}) $ to $A(T')$. 

	\item Here we allow multiple arcs but no self loop.

\end{itemize}

\item For each $ i \in [q] $, as all the \scc's of $\mathcal{C}_i$ forms a DAG so  there exists a unique topological ordering of the vertices corresponding to $\mathcal{C}_i$. We denote this ordering as $ \sigma_i $.

\item For each $C \in \mathcal{C}$, we color the vertex $v_C$ with the same color as the color class, the \scc $C$ belongs to. In other words, color of $v_C$ is $i$ if $C \in \mathcal{C}_i$ in the instance \csfast.

% \item $S \coloneqq \{v_C: C=T[s], s \in S\}$. 




\end{enumerate}

Observe that for each vertex $s \in S$, the graph $T[s]$ forms a strongly component in $\mathcal{C}$. Notice that $|V(T')| \leq |V(T)|$ and  $|A(T')| \leq |A(T)|$. Also, every non-monochromatic arc corresponds to some arc in $T'$. Now  in $T'$, our goal  is to find $ S $-fas $Z' \subseteq A(T')$ of size at most $k $ such that no arc of $Z' $ is monochromatic. Below in \cref{lem:equi}, we  demonstrates that the instances $(T,S,k,q)$ and  $(T',S',k',q)$ are equivalent to the problem \csfast.


%e equivalence between the \csfast and \ecsfast problems.

\begin{lemma}\label{lem:equi}
$(T,S,k,q)$ is a {\sc Yes} instance for \csfast if and only if $(T',S,k,q)$ is a {\sc Yes} instance for \csfast.
\end{lemma}

\begin{proof}
In the forward direction, assume that  $F$ is  a solution to $(T,S,k,q)$. We can assume that $F$ is minimal. By the property of our problem, no arc of $F$ is monochromatic, so each arc in $F$ corresponds to some arc in $T'$.  Let $F'$ be the set of arcs in $T'$ corresponding to $F$ in $T$. We claim that $F'$ is also a solution to $(T',S',k',q)$. If not, then there exists a $S$-cycle, say $C'$ in $T'-F'$. Now, considering $C'$, we can retrieve a $S$-cycle $C$ in $T-F$ in the following way. Pick an arc $e=(v_{C_1}, v_{C_2} )$ in the cycle $C'$. If the arc $e$ is monochromatic in $T'$, then we get an arc $(u,v)$ for all pair of vertices  $u \in V(C_1)$ and $v \in V(C_2)$ in $T-F$ (as $F$ uses no monochromatic arc). If the arc $e$ is not monochromatic  in $T'$, then we get a directed path from $u$ to $v$ for all pair of vertices  $u \in V(C_1)$ and $v \in V(C_2)$ in $T-F$. Combining all these path and arcs we get a closed walk passing through $S$-vertices in $T-F$. For that closed walk, we can retrieve a $S$-cycle in $T-F$. This is in contradiction to the fact that $F$ is a solution to $(T,S, k, q)$.


The backward direction is analogous to the forward direction.  
\end{proof}


