\noindent As discussed, the complete information assumption will not hold in many security scenarios which we shall handle with a decision-analytic approach. %
  Let $D$'s expected utility  be
$\psi_D(d) = \int \psi_D(d,a)\, p_D(a) \dd a $, where $\psi_D (d,a) = \int u_D (d, \theta )\, p_D(\theta \vert d,a) \dd \theta $.\footnote{We assume here that $A$, $D$ and $\Theta$ are all continuous. Discrete cases are handled in a similar manner.}  Her optimal decision will be $d^\opt_\text{ARA} = \argmax_{d \in \Dcal}\, \psi_D(d)$. Finding 
 it requires estimating $p_D(a)$, $D$'s assessment of $A$ choosing attack $a$. For this, consider $A$'s problem who aims to find
 $a^* = \argmax_{a \in \Acal} \int \psi_A(d, a)  p_A(d) \dd d,
$ with $\psi_A(d,a)=\int u_A(a,\theta)p_A(\theta|d,a)\dd \theta.$
However, as \cite{KEENEY} argues, $D$ has no access to 
   $A$ to assess $u_A$ and $p_A$, and, therefore, 
   lacks complete knowledge about $A$'s utilities and probabilities.
   Adopting a Bayesian approach, let us  
  model such uncertainty through random utilities  $U_A(a, \theta)$ and random probabilities $P_A(\theta | d, a)$ and $P_A (d)$, defined over a common probability space $(\Omega, \cal F, \Pcal)$ with atomic elements $\omega\in \Omega$ \citep{Chung}. Then, 
the random optimal attack is
$ 
A^*  = \argmax_{x \in \Acal} \int \Psi_A (d,x) \cdot P_A  (d) \dd d, 
$ 
with $\Psi_A(d,x) = \int U_A(x,\theta)P_A(\theta|d,x)\dd \theta$, and we make $p_D(A\leq a) =  Pr \left[ A^* \leq a  \right]= {\cal P} \{ \omega :  A^{*\omega } 
\leq  a  \}$. %
This defines $p_D(a)$, the
missing ingredient when searching for $d^*_{ARA}$. Implementing this requires the specification of $U_A(a, \theta)$, $P_A(\theta | d,a)$, and $P_A(d)$. Of these, eliciting $P_A(d)$ has a recursive element as we need to think about how the attacker reasons about the defender which, in turn, begs for thinking about 'how the defender thinks about how the attacker thinks about the defender', and so on. This leads to a recursion similar to the level-$k$ scheme described in \citet{rios2012adversarial}. 
As mentioned, we only consider level-2 defenders,
although the scheme described extends to higher levels in the thinking hierarchy.

 As seen,
ARA models entail integration and optimization procedures that may be computationally challenging. This paper proposes efficient APS-based methods to handle them. First, for the Defender problem, assuming with no loss of generality that $u_D$ is positive, we introduce an augmented distribution (AD) over $(d,a, \theta)$ for $D$'s problem defined through 
$
\pi_D(d, a, \theta) \propto u_D(d,\theta) \cdot p_D(\theta \vert d,a)\cdot p_D(a)$.
Observe that its marginal $\pi_D(d)$ in $d$ is $\iint u_D (d, \theta) \cdot p_D(\theta \vert d, a)\cdot p_D(a) \dd \theta \dd a$ which is proportional to  $\psi_D(d)$. Consequently, $d^\opt_\text{ARA}  = \mode{(\pi_D(d))}$. In such a way, one would just need to sample $(d, a, \theta )\sim \pi_D(d, a, \theta)$ and estimate its mode in $d$ to approximate $d^*_{ARA}$.  Sampling may be performed using Markov Chain Monte Carlo (MCMC) methods. In particular, Algorithm \ref{alg:ARA_APS_framework}b) ($\texttt{DAPS}$ function) illustrates a Metropolis-Hastings (MH) \citep{French:2000} version.  Besides the Defender's utility $u_D$ and probabilities $p_D$, \texttt{DAPS} takes as input the number $N$ of MCMC samples and the candidate generating distribution $g_D$ within the function $\texttt{MH}$. 

{\small
\begin{algorithm}[H]
\textcolor{black}{
\linespread{0.7}\selectfont
\SetKwFunction{Fatk}{MH}
\SetKwProg{Fn}{function}{:}{}
\Fn{\Fatk{$g$, $u$, $x$, $x'$, $y$, $y'$ $\theta$, $\theta '$}}{
Compute acceptance probability $
    \alpha = \min \left \lbrace 1, \frac{u \left( x, \theta \right) \cdot g\left(x' \vert x \right) }{u \left( x', \theta ' \right) \cdot g\left( x \vert x' \right) } \right \rbrace
    $\;
    $\text{ Set  $z$= }\begin{cases}  (x,y, \theta)    & $\text{with probability $\alpha$ }$  \\  (x',y', \theta')    & $\text{with probability $1-\alpha$ }$  \end{cases}$\;
\textbf{return} $z$ \;}
\;
\linespread{0.7}\selectfont
\SetKwFunction{Fatk}{DAPS}
\SetKwProg{Fn}{function}{:}{}
\Fn{\Fatk{$N$, $u_D$, $p_D$, $g_D$}}{
\Initialize{ $d^{(0)}$  }
Draw $a^{(0)} \sim p_D( a )$\;
Draw $\theta^{(0)} \sim p_D(\theta \vert d^{(0)}, a^{(0)})$\;
\For{$i=1$ \KwTo $N$} {
    Propose new defense $\tilde{d} \sim g_D(\tilde{d} \vert d^{(i-1)})$\;
    Draw $\tilde{a} \sim p_D( a )$\; 
    Draw $\tilde{\theta} \sim p_D(\theta \vert \tilde{d}, \tilde{a} )$\;
    $(d^{(i)} , a^{(i)}, \theta^{(i)})$ = \texttt{MH}$(g_D,u_D,\tilde{d},d^{(i-1)}, \tilde{a},a^{(i-1)},\tilde{\theta},\theta^{(i-1)})$\;
    }
Discard burn-in samples and construct $\widehat{d}^\opt_\text{ARA}$, a consistent estimator of the mode of the marginal augmented distribution, using the remaining $d$ samples\;
%
\textbf{return} $\widehat{d}^\opt_\text{ARA}$ \;}
\;
\SetKwFunction{Fatk}{AAPS}
\SetKwProg{Fn}{function}{:}{}
\Fn{\Fatk{$M$, $U_A$, $P_A$, $g_A$}}{
\Initialize{ $a^{(0)}$}
Draw $u_A(a, \theta) \sim U_A(a,\theta)$\;
Draw $p_A(\theta \vert d,a) \sim P_A(\theta \vert d,a)$\;
Draw $p_A(d) \sim P_A(d)$\;
Draw $d^{(0)} \sim p_A(d)$\;
Draw $\theta^{(0)} \sim p_A(\theta \vert d^{(0)}, a^{(0)})$\;
\For{$i=1$ \KwTo $M$} {
	Propose new attack $\tilde{a} \sim g_A(\tilde{a} \vert a^{(i-1)})$ \;
	Draw $\tilde{d} \sim p_A(d)$\;
	Draw $\tilde{\theta} \sim p_A(\theta \vert \tilde{d}, \tilde{a})$\;
    $( a^{(i)}, d^{(i)}, \theta^{(i)})$ = \texttt{MH}$(g_D,u_D,\tilde{a},a^{(i-1)},\tilde{d},d^{(i-1)},\tilde{\theta},\theta^{(i-1)})$ \;
    }
%
Discard burn-in samples and construct $a^\opt$, a consistent estimator of the mode of the marginal augmented distribution, using the remaining $ a $ samples\;
%
\textbf{return} $a^\opt$\;
}}
\caption{\small a) \texttt{MH}: MH algorithm. b) \texttt{DAPS}: MH Defender APS to approximate\textcolor{white}{'}ARA solution. c) \texttt{AAPS}: MH Attacker APS to approximate sample from $p_D(a)$. }\label{alg:ARA_APS_framework}
\end{algorithm}
}

\vspace{0.25cm}

 $\texttt{DAPS}$ requires the ability to sample from $a \sim p_D(a)$. To produce such samples, assuming that $U_A^{\omega}$ is 
a.s.\ positive, consider the attacker random AD (RAD) model, defined for each $\omega \in \Omega$ through,
$ \Pi_A^{\omega}(d, \theta,a) \propto  U^{\omega}_{A}(a, \theta)\cdot P^{\omega}_A(\theta \vert d, a)\cdot P ^{\omega}_A(d)$.
Then, as before, a.s$.$ the mode of the marginal of $\Pi^\omega(d,\theta,a)$ in $a$ coincides with  $A^{*\omega}$. Consequently, by sampling $u_A(a, \theta) \sim U_A(a, \theta)$, $p_A(\theta \vert d, a) \sim P_A(\theta \vert d, a)$, and $p_A(d) \sim P_A(d)$, one can build $\pi_A(d, \theta, a) \propto u_A(a, \theta)p_A(\theta \vert d, a)p_A(d)$ which conforms a sample from $\Pi_A (d, \theta, a)$ (Algorithm \ref{alg:ARA_APS_framework}c). Therefore, $\text{mode}(\pi_A(a))$ is a sample from $A^*$,  thus providing a mechanism ($\texttt{AAPS}$) to sample from the target distribution. A repeated application of \texttt{AAPS} (Algorithm \ref{alg:ARA_APS_framework}c) would provide a sample of the required size from $A^{*}$. 
 Input to \texttt{AAPS} includes the number $M$ of samples, the candidate generating distribution $g_A$ for the algorithm, and the 
 Attacker's random utility $U_A$ and probabilities $P_A$.
 %

Under mild conditions, the convergence of Algorithm \ref{alg:ARA_APS_framework}b 
to $d_{ARA }^*$ (supported by that of Algorithm \ref{alg:ARA_APS_framework}c) follows when using consistent mode estimators,
 as  proved in \ref{sec:app_proof_pro}.

\begin{proposition}
Suppose that
\begin{enumerate}
\item $u_D$ and, a.s., the utilities in the support of $U_A$ are positive and, respectively, continuous in $(d,\theta)$ and $(a, \theta)$.
\item The Defender's and Attacker's decision sets are compact.
 \item $p_D(\theta|d,a)$ and, a.s., the distributions in the support of $P_A(\theta|d,a)$ are continuous in $a$ and $d$, respectively, and positive in $(d,a)$.
 \item The proposal generating distributions $g_D$ and $g_A$ have, respectively, support $\mathcal{D}$ and $\mathcal{A}$.
\end{enumerate}

\noindent Then, Algorithm \ref{alg:ARA_APS_framework}b defines a Markov chain with stationary distribution $\pi_D(d, \theta, a)$. Moreover, a consistent mode estimator based on the marginal samples of $d$ from this Markov chain a.s.\ approximates $d^{*}_{ARA}$.
\end{proposition}


\noindent Observe that Algorithm \ref{alg:ARA_APS_framework} constructs two APS: one for the Defender problem (function $\texttt{DAPS}$), and another for the Attacker ($\texttt{AAPS}$), which is iteratively called.



