\pagebreak
Let us briefly discuss how the single-stage approach in Section \ref{sec:single_stage_parallel} extends to a 2-stage case. Figure \ref{fig:n_sim_DA_ids} presents the (a) defender's and (b) attacker's problems in this case. Assuming that the utility function $u_D(d_1,d_2,\theta_1,\theta_2)$, and the distributions $p_D(\theta_2|d_2,\theta_1, a_2)$, $p_D(a_2|a_1)$, $p_D(a_1)$, and $p_D(\theta_1|d_1,a_1)$ are available, we
 proceed as follows, using \cite{Shachter1986}'s algorithm to 
  solve the Defender's problem.


\begin{enumerate}[noitemsep]
    \item Remove chance node $\theta_2$, computing  $\psi_D(d_1,d_2,\theta_1, a_2)$=$\int$$u_D(d_1,d_2,\theta_1,\theta_2)p_D(\theta_2|d_2,\theta_1,a_2)$$\dd\theta_2$.
    %
    \item Remove chance node $A_2$, computing 
    $\psi_D(d_1,d_2,\theta_1,a_1) = \int \psi_D(d_1,d_2,\theta_1,a_2)p_D(a_2|a_1)\dd a_2$.
    %
    \item Remove chance node $\theta_1$, computing  $\psi_D(d_1,d_2,a_1) = \int \psi_D(d_1,d_2,\theta_1,a_1)p_D(\theta_1|a_1,d_1) \dd \theta_1$.
    %
    \item Remove chance node $A_1$, computing $ \psi_D(d_1,d_2) = \int \psi_D(d_1,d_2,a_1)p_D(a_1)\dd a_1.$
    %
    \item Remove decision node $D_2$, computing  $\psi_D(d_1) = \max_{d_2}\psi_D(d_1,d_2)$ and storing   $d_2^{*}(d_1) = \\\argmax_{d_2}\psi_D(d_1,d_2)$. 
    %
    \item Remove decision node $D_1$, computing $d_1^{*} = \argmax_{d_1} \psi_D(d_1)$.
%
\end{enumerate}


