\paragraph{Remark 1} {\em We could combine steps 5 and 6, jointly removing nodes $D_1$ and $D_2$, to solve for $(d_1^{*},d_2^{*}) = \argmax_{(d_1,d_2)} \psi_D(d_1,d_2)$. However in some contexts it is of interest to provide a full second-stage policy $d_2^{*}(d_1)$. In particular, this will be relevant when addressing A's problem.} $ \hfill \triangle$
\vspace{.05in}
%

\pagebreak
\noindent  Interestingly, we may implement the above six steps through two DAPS reductions:
\begin{itemize}[noitemsep,label={},leftmargin=0pt]
\item {\em DAPS1}. Since  $ d_2^{*}(d_1)$=$\argmax_{d_2}\iiiint u_D(d_1,d_2,\theta_1,\theta_2)  p_D(\theta_2|d_2,\theta_1,a_2)p_D(a_2|a_1)p_D(\theta_1|d_1,a_1)\\ p_D(a_1)\dd a_1 \dd \theta_1 \dd a_2 \dd \theta_2$, we aggregate steps 1-5 by defining the AD 
 $\pi(d_2,\theta_1,\theta_2,a_1,a_2|d_1)\propto u_D(d_1,d_2,\theta_2)p_D(\theta_2|d_2,\theta_1,a_2)p_D(a_2|a_1)p_D(\theta_1|d_1,a_1)p_D(a_1)$,
        so that $\text{mode}(\pi(d_2|d_1)) = d_2^{*}(d_1)$. Next, proceed by simulating from $\pi(d_2,\theta_1,\theta_2,a_1,a_2|d_1)$ and, based on a sample from it, obtain the corresponding sample from $\pi(d_2|d_1)$, using it to get a consistent estimate of its mode.   

   \item {\em DAPS2.} This handles step 6 and uses $d_1^{*}=\argmax_{d_1}\psi_D(d_1)$. Although 
    obvious,\footnote{It is operationally obvious but computationally convenient to provide, later on, a unified approach, when facing general problems.} we view it through an AD with $\pi(d_1)\propto\psi_D(d_1)$ from which we sample to estimate its mode $\hat{d_1^{*}}$.
    %
\end{itemize}

  As in Section \ref{sec:single_stage_parallel}, whereas $u_D(d_1,d_2,\theta_1, \theta_2)$, $p_D(\theta_2|d_2, \theta_1,a_2)$, and $p_D(\theta_1|d_1,a_1)$ are standard to elicit from a decision analytic point of view, $p_D(a_2|a_1)$ and $p_D(a_1)$ include strategic elements that need to be somehow reflected. For this, let us deal with the attacker problem from the defender point of view (Figure \ref{fig:n_sim_DA_ids}b), which is symmetric to her problem. %  
    If, as in Section 2.1, we model our uncertainty about its ingredients with a random utility function $U_A$ and random probability distributions $P_A$, we would solve the attacker problem through two AAPS reductions:

\begin{itemize}[noitemsep,label={},leftmargin=0pt]
\item {\em AAPS1.} Define the RAD
$\Pi(a_2,\theta_1,\theta_2,d_1,d_2|a_1) \propto U_A(a_1,a_2,\theta_1,\theta_2) P_A(\theta_2|a_2,\theta_1,d_2)P_A(d_2|d_1)
\allowbreak P_A(\theta_1|a_1,d_1)P_A(d_1) $, 
to estimate the random optimal decision $\hat{A}_2^{*}(a_1)$. From it, estimate $\hat{p}_D(a_2|a_1)$.

\item {\em AAPS2.} Define the RAD $\Pi(a_1)\propto \Psi(a_1)$. From it sample the random optimal attack $\hat{A}_1^{*}$, and deduce $\hat{p}_D(a_1)$.\footnote{For completeness, we describe  estimations of $\hat{p}_D(a_2|a_1)$ and $\hat{p}_D(a_1)$ but,
 effectively, we only require samples from them.}
\end{itemize}

\noindent The approach is actually general as Proposition \ref{prop:n_sim} states. We omit its proof since it is a particular case of the more general Proposition \ref{prop:gen_algo} below.


\begin{proposition}
\label{prop:n_sim}
An n-stage simultaneous game can be solved from an ARA perspective by using n DAPS reductions and $n$ AAPS reductions.     
\end{proposition}


