\subsection{Methodology motivation}
\label{sec:mot_method}

%
   Let us first solve $D$'s problem conceptually. Assume for now that we have available the required utilities %
 and probabilities. % 
 Then, we treat $D$'s ID as follows, using \cite{Shachter1986} reduction operations.

\begin{itemize}[noitemsep,label={},leftmargin=0pt]
 \item $\mathcal{D}_1$: Remove chance node $\Theta_2$, computing $\psi_D(d_1, d_2, \theta_1, a_2)$=$\int u_D(d_1,d_2,\theta_2)p_D(\theta_2|d_2,a_2,\theta_1)d\theta_2$.
    %
    \item  $\mathcal{D}_2$: Remove decision node $D_2$, computing the optimal  $d_2^{*}(d_1,a_2,\theta_1) = \argmax_{d_2}\psi_D(d_1, d_2,\theta_1, a_2)$ and storing the optimal expected utilities $\psi_D(d_1,a_2,\theta_1) = \max_{d_2}\psi_D(d_1,d_2,\theta_1,a_2)$.
    %
    \item $\mathcal{D}_3$: Remove chance node $\Theta_1$, computing $\psi_D(d_1,a_1,a_2) = \int \psi_D (d_1,a_2, \theta_1)p_D(\theta_1|d_1,a_1,a_2)\dd\theta_1 $. 
    %
    $\mathcal{D}_4$: Remove chance node $A_2$, computing $\psi_D(d_1,a_1) = \int \psi_D(d_1,a_1,a_2)p_D(a_2|d_1,a_1)\dd a_2$. 
    %
   \item  $\mathcal{D}_5$: Remove chance node $A_1$, computing $\psi_D(d_1) = \int \psi_D(d_1,a_1)p_D(a_1)\dd a_1$. %
     \item $\mathcal{D}_6$: Remove decision node $D_1$, obtaining the 
     optimal first stage decision $d_1^{*} = \argmax_{d_1} \psi_D(d_1)$.
    %
\end{itemize}

\noindent Then, the optimal strategy for $D$ would consist of selecting $d^{*}_1$ at node $D_1$, and  %
 $d_2^{*}(d_1^{*},a_2,\theta_1)$ at node $D_2$, given the $a_2$ and $\theta_1$ observed. Note that, in principle, to implement steps $\mathcal{D}_3$-$\mathcal{D}_6$, it is not actually necessary to store the optimal action $d_2^{*}(d_1,a_2, \theta_1)$,
 %
   but just the 
 optimal value $\psi_D(d_1,a_2,\theta_1)$, from which we  
  can subsequently reconstruct $d_2^{*}(d_1^{*},a_2, \theta_1)$. This point is particularly relevant in continuous domains, as it allows for a reduction in storage requirements.  %
Importantly, assuming with no loss of generality, that the utility function $u_D(d_1,d_2,\theta_2)$ is positive, the previous problem may be solved by applying two APS steps:

\begin{itemize}[noitemsep,label={},leftmargin=0pt]
\item {\em DAPS1.} Aggregate steps $\mathcal{D}_1$-$\mathcal{D}_2$, corresponding to $d_2^{*}(d_1,a_2,\theta_1)$=$\argmax_{d_2} \int u_D(d_1,d_2,\theta_2) p_D(\theta_2|\\d_2,a_2,\theta_1)\dd \theta_2$. 
  For this, define the AD $ \pi(d_1,d_2,\theta_2|a_2,\theta_1)\propto u_D(d_1, d_2,\theta_2) p_D(\theta_2|d_2,a_2,\theta_1)$. 
    By sampling from this distribution and consistently estimating $\text{mode}\big(\pi(d_1|a_2,\theta_1)\big)$, we approximate $d_2^{*}(d_1,a_2,\theta_1)$ and store $\widehat{\psi}_D(d_1,a_2,\theta_1) = \pi(d_1, d_2^{*}(d_1,a_2,\theta_1),\theta_2|a_2,\theta_1)$, which is proportional to $\psi_D(d_1,a_2,\theta_1)$.
\item {\em DAPS2.} Aggregate steps $\mathcal{D}_3$-$\mathcal{D}_6$ corresponding to $ d_1^{*} = \argmax_{d_1}   \iiint \widehat{\psi_D}(d_1,a_2,\theta_1) p_D(\theta_1|d_1,a_1,\\a_2) p_D(a_2|d_1,a_1)p_D(a_1)\dd \theta_1 \dd a_2 \dd a_1.$  For this, define the AD 
 \begin{align}   
 \label{eq:DAPS2ad}
\pi(d_1,a_2,\theta_1,a_1) \propto \widehat{\psi}_D(d_1,a_2,\theta_1)p_D(\theta_1|d_1,a_1,a_2)p_D(a_2|d_1,a_1)p_D(a_1). 
\end{align}
    By sampling from it and estimating $\mode(\pi(d_1))$
     consistently, we approximate $d_1^{*}$.
\end{itemize}
Of $D$'s required utilities and probabilities,
%
  $p_D(a_2|d_1,a_1)$ and $p_D(a_1)$ demand strategic thinking about $A$'s problem. We could solve this should we have the Attacker's utility function, %
  and probabilities.
  %
  However, as argued before, typically $D$ will not be able to obtain such elements precisely. Suppose we represent the corresponding uncertainty with a distribution of random utilities and 
   probabilities $F\sim (U_A(a_1,a_2,\theta_2), P_A(\theta_2|\theta_1,d_2,  a_2), P_A(d_2|d_1,\theta_1,  a_2), P_A(\theta_1|d_1, a_1,a_2), \\P_A(d_1))$ to solve $A$'s problem as follows, where
random expected utilities and random optimal alternatives are 
introduced.
\begin{itemize}[noitemsep,label={},leftmargin=0pt]
\item $\mathcal{A}_1$: Remove $\Theta_2$, computing   $\Psi_A(a_1,a_2,\theta_1,d_2) = \int U_A(a_1,a_2,\theta_2)P_{A}(\theta_2| \theta_1,d_2,a_2) \dd \theta_2$.
    %
\item $\mathcal{A}_2$: Remove $D_2$, computing  $\Psi_A(d_1,\theta_1, a_1, a_2) =  \int \Psi_A(a_1,a_2, \theta_1, d_2)P_A(d_2|d_1,\theta_1,a_2) \dd d_2$. 
    %
\item $\mathcal{A}_3$: Remove $\Theta_1$, computing $\Psi_A(d_1,a_1, a_2) = \int \Psi_A(d_1,\theta_1,a_1,a_2)P_A(\theta _1|d_1,a_1,a_2)\dd{\theta_1}$. 
    %
\item  $\mathcal{A}_4$: Remove $A_2$, computing $ A_2^{*}(d_1,a_1) = \argmax_{a_2} \Psi_A(d_1,a_1,a_2)$
     %
      and storing $\Psi_A(d_1,a_1)$ =$\\\Psi_A(d_1,a_1, A_2^{*}(d_1,a_1))$.
      %
 \item  $\mathcal{A}_5$: Remove $D_1$, computing   $\Psi(a_1) = \int \Psi_A(d_1,a_1)P_A(d_1)\dd d_1$. 
    %
\item  $\mathcal{A}_6$: Remove $A_1$, finding  $A_1^{*} = \argmax_{a_1}\Psi_A(a_1)$.
     %
\end{itemize}

\noindent Through $\mathcal{A}_1$-$\mathcal{A}_6$, we are able to obtain samples from $A_2^{*}(d_1,a_1)$ and $A_1^{*}$ that, respectively, correspond to samples from $p_D(a_2|d_1,a_1)$ and $p_D(a_1)$, the missing ingredients to implement DAPS1-DAPS2. As in $D$'s problem, we only require the random optimal value $\Psi_A(d_1,a_1) = \Psi_A(d_1,a_1, A_2^{*}(d_1,a_1))$  to implement $\mathcal{A}_5$-$\mathcal{A}_6$, which will be relevant when addressing nodes with continuous domains. However, in contrast to the Defender's problem, it is necessary to compute $A_2^{*}(d_1,a_1)$ (or at least approximate it in continuous problems) as it will be used in DAPS2. %
Again, APS allows us to implement the $\mathcal{A}_1$-$\mathcal{A}_6$ operations in a principled manner, through
\begin{itemize}[noitemsep,label={},leftmargin=0pt]
\item {\em AAPS1.} Aggregates steps $\mathcal{A}_1-\mathcal{A}_4$ defining
$A_2^{*}(d_1,a_1) = {\argmax_{a_2} \iiint}  U_A(a_1,a_2,\theta_2)  P_A(\theta_2|\theta_1,d_2,\\a_2)P_A(d_2|d_1,\theta_1,a_2)P_A(\theta_1|d_1,a_1,a_2)\dd \theta_2 \dd d_2 \dd \theta_1.$ 
Consider the  RAD  
$ \Pi(a_1,a_2,\theta_2,d_2,\theta_1|d_1,a_1)\propto U_A(a_1,a_2,\theta_2) P_A(\theta_2|\theta_1, d_2, a_2) P_A(d_2|d_1,\theta_1,a_2)P_A(\theta_1|d_1,a_1,a_2)$.
By sampling from it, which entails previously sampling from each of the aforementioned distributions, we can then estimate $\text{mode}(\Pi(a_2|d_1,a_1))$ consistently, therefore estimating $A_2^{*}(d_1,a_1)$.
\item {\em AAPS2.} Aggregates steps $\mathcal{A}_5-\mathcal{A}_6$. We solve for
\begin{equation*}
A_1^{*} =  \argmax_{a_1} \int \Psi_A(d_1,a_1)P_A(d_1)\dd d_1.
\end{equation*}
Consider the RAD $\Pi(a_1,d_1) \propto \Psi_A(d_1,a_1)P_A(d_1).$ By sampling from it, which entails sampling from $\Psi_A(d_1,a_1)$ and $P_A(d_1)$, we consistently estimate $\text{mode}(\Pi(a_1))$ to approximate $A_1^{*}$.
\end{itemize}

\noindent   In conclusion, by solving two APS for the Defender (DAPS1 and DAPS2) and two random APS (RAPS) for the attacker (AAPS1 and AAPS2) we are conceptually capable of solving the problem. 

Importantly, the approach is actually general. Before discussing this, let us analyse two final examples that introduce additional computational issues not covered in the case. 

\paragraph{Example 1}{Consider $D$'s ID in Figure \ref{fig:example_prop}. Assume we have $u_D(x_3,d)$, $p_D(x_1|d,x_2)$, $p_D(x_2|x_3)$ and $p_D(x_3)$ available.} Appealing to  Shachter's (1986) algorithm, we would go through the steps

