  \centering
  \includegraphics[width=0.45\linewidth]{Figures/BAID_example_basic_for_prop_mod_.png} 
  \caption{\small ID for problem where all nodes affected by arc inversion are reduced before node $D$.} \label{fig:example_prop}
\end{figure}

\begin{itemize}[noitemsep,label={},leftmargin=0pt]
\item \noindent {\em Invert arc $X_2-X_3$}, with updated probabilities $p_D(x_3|x_2) = p_D(x_2|x_3)p(x_3)/p_D(x_2)$ and $p_D(x_2) = \int p_D(x_2|x_3)p_D(x_3) \dd x_3$.
\item  {\em  Eliminate $X_3$,} obtaining the expected utility $\psi_D(x_2,d) = \int u_D(x_3, d) p_D(x_3|x_2) \dd x_3$. 
\item {\em  Invert arc $X_1$-$X_2$} with updated probabilities $p_D(x_2|x_1,d) = p_D(x_2)p_D(x_1|x_2,d)/p_D(x_1|d)$ and $p_D(x_1|d) = \int p_D(x_1|x_2,d) p_D(x_2)\dd x_2$. 
\item {\em Eliminate $X_2$,} obtaining the expected utility $\psi_D(x_1,d) = \int \psi_D(x_2,d)p_D(x_2|x_1,d)\dd x_2$. 
\item {\em Eliminate $X_1$,} obtaining the expected utility $\psi_D(d) = \int \psi(x_1,d)p(x_1|d) \dd x_1$. 
\item {\em Eliminate $D$,} obtaining the optimal decision $d^{*} = \argmax \psi_D(d)$.
\end{itemize}

\noindent Observe now that, assuming that $u_D(x_3,d)$ is positive, this can be solved in a single step by considering the AD 
 $\, \pi(d,x_1,x_2,x_3) \propto u_D(x_3,d)p_D(x_1|d)p_D(x_2|x_1,d)p_D(x_3|x_2)    \propto  u_D(x_3,d)p_D(x_1|d,\\x_2)p_D(x_2|x_3)p_D(x_3),$  
defined using only the terms originally available.

Something similar would occur in an Attacker's ID. Assume that $A$'s   problem is also described by an ID as that in Figure \ref{fig:example_prop}. If 
$D$ has access to the random probabilities and utilities $U_A(x_3,d)$, $P_A(x_1|d,x_2)$, $P_A(x_2|x_3)$, $P_A(x_3)$, the problem may be solved 
 with the RAD $\Pi(d,x_1,x_2,x_3) \propto  U_A(x_3,d)P_A(x_1|d,x_2)P_A(x_2|x_3)P_A(x_3)$, again defined using only the original terms. $\hfill\triangle$

\paragraph{Example 2.} Consider the Defender problem in Figure \ref{fig:example_prop_2}. We have available $u_D(d,x_1)$, $p_D(x_1)$ and $p_D(x_2|x_1)$.
 The steps followed to solve the problem are

