\begin{equation*}
 \psi_D(x_2,d) = \int u_D(x_1,d)\frac{p_D(x_2|x_1)p_D(x_1)}{p_D(x_2)}\dd x_1\propto\int u_D(x_1,d)p_D(x_2|x_1)p_D(x_1)\dd x_1.
