\section{Problem Definition}

\label{sec:problem_def}

In this section, we give the definitions of the graph data model, neighbor difference semantics, and the \textit{subgraph similarity search under aggregated neighbor difference semantics} (S$^3$AND) problem.


\subsection{Graph Data Model}

We first provide the formal definition of a large-scale data graph $G$. 

\begin{definition}
    \textbf{(Data Graph, \bm{$G$})} A data graph $G$ is in the form of a triple $(V(G), E(G), \Phi(G))$, where $V(G)$ is a set of vertices, $v_i$, in graph $G$, each with a keyword set $v_i.W$, $E(G)$ represents a set of edges $e(v_i, v_j)$ (connecting two ending vertices $v_i$ and $v_j$), and $\Phi(G)$ is a mapping function: $V(G) \times V(G) \rightarrow E(G)$. %Each vertex $v_i \in V(G)$ has a keyword set $v_i.W$.
    \label{def:data_graph}
\end{definition}

% (users)
% (relationships between users)

%each vertex $v_i$ contains topic keywords in a set $v_i.W$. 

Examples of the data graph in Definition \ref{def:data_graph} include social networks \cite{Al-BaghdadiL20, rai2023top, subramani2023gradient}, bioinformatics networks \cite{GliozzoPGCV23}, financial transaction networks \cite{SongZK23}, and so on.


\subsection{Aggregated Neighbor Difference Semantics}
\label{subsec:AND}

\noindent {\bf The Vertex-to-Vertex Mapping, $M: V(q)\to V(g)$:} Consider a target (query) graph pattern $q$ and a subgraph $g$ of data graph $G$ with the same graph size, that is, $|V(g)| = |V(q)|$. We say that there is a vertex-to-vertex mapping, $M: V(q)\to V(g)$, between $q$ and $g$, if each vertex $q_j \in V(g)$ has a 1-to-1 mapping to a query vertex $q_j\in V(q)$, such that their keyword sets satisfy the condition that $q_j.W \subseteq v_i.W$.

\noindent {\bf The Vertex Subset Mapping Function, $\mu(\cdot)$:} Accordingly, we denote $\mu(\cdot)$ as a mapping function from any vertex subset, $V'(q)$, of $V(q)$ to its mapping subset, $V'(g)$, of $V(g)$ (via the vertex-to-vertex mapping $M$). That is, we have $\mu(V'(q)) = V'(g)$, where any vertex $q_j \in V'(q)$ is mapped to a vertex $M(q_j) = v_i\in V'(g)$.


%with the 1-to-1 mappings between their vertices, where $|V(g)| = |V(q)|$ holds (i.e., with the same graph size). Without loss of generality, we assume that any vertex $v_i \in V(g)$ has a 1-to-1 mapping to a vertex $q_j\in V(q)$, denoted as $M: V(q)\to V(g)$, where their keyword sets satisfy the condition that $q_j.W \subseteq v_i.W$.


\noindent {\bf Neighbor Difference Semantics, $ND(q_j, v_i)$:} Let $N(v_i)$ be a set of 1-hop neighbors of vertex $v_i \in V(g)$ in the subgraph $g$. Similarly, $N(q_j)$ is a set of $q_j$'s 1-hop neighbors in the query graph $q$. 


Then, for each vertex pair $(v_i, q_j)$ between $g$ and $q$, their \textit{neighbor difference}, $ND(q_j, v_i)$, is defined as the number of (matching) 1-hop neighbors (or edges) that $v_i$ is missing, based on the target vertex $q_j$ (and its neighbors). Formally, we have the following definition of the neighbor difference semantics.

%%(i.e., $|N(q_j) - N(v_i)|$, where ``-'' is a \textit{set difference} operator).


% {\color{red}
\begin{definition} \textbf{(Neighbor Difference, \bm{$ND(q_j, v_i)$})} Given a target vertex, $q_j$, of a query graph $q$, a vertex, $v_i$, of a subgraph $g$, and a mapping function $\mu(\cdot)$ from any subset of $V(q)$ to its corresponding subset of $V(g)$ (via vertex-to-vertex mapping $M$), their \textit{neighbor difference}, $ND(q_j, v_i)$, is given by:
    \begin{equation}
        ND(q_j, v_i)=|\mu(N(q_j)) - N(v_i)|,\label{eq:ND}
    \end{equation}
where $N(\cdot)$ is a set of 1-hop neighbor vertices,  ``$-$'' is a \textit{set difference} operator, and $|\cdot|$ is the cardinality of a set. 
\label{def:neighbor_diff}
\end{definition}
% }


Intuitively, in Definition \ref{def:neighbor_diff}, for each vertex pair $(q_j,v_i)$ in $q$ and $g$, the neighbor difference, $ND(q_j, v_i)$, is given by the number of missing edges $e(v_i, v_j)$ with an ending vertex $v_i$ (when their corresponding edges $e(q_j, q_j)$ in the target query graph $q$ exist).

