\begin{definition}
    \textbf{(Aggregated Neighbor Difference, \bm{$AND(q,g)$})} Given a query graph $q$, a subgraph $g$, and a 1-to-1 vertex mapping $M$ from $V(q)$ to $V(g)$ (note: $|V(q)|=|V(g)|$), the \textit{aggregated neighbor difference}, $AND(q,g)$, between $q$ and $g$ is defined as the aggregation over neighbor differences of all the matching vertex pairs $(q_j, v_i)$, i.e.,
    \begin{equation}
        AND(q,g)=f\left(\left\{ ND(q_j, v_i) | \forall (q_j, v_i), s.t. M(q_j) = v_i \right\}\right),
        \label{eq:AND}
    \end{equation}
    where $ND(q_j, v_i)$ is given by Eq.~(\ref{eq:ND}), and $f(S)$ is an aggregate function (e.g., MAX, AVG, or SUM) over a set $S$.
\label{def:AND}
    %$\Delta(q_j,v_g)$ denotes the neighborhood difference of a node $q_j$ to a neighbor node $v_g$.
\end{definition}

