\subsection{AND Lower Bound Pruning}
\label{subsec:AND_bound_pruning}

{\color{black}


According to Definition~\ref{def:S3AND}, the aggregated neighbor difference (AND) between a subgraph $g$ and a query graph $q$ must satisfy the AND constraint, that is, $AND(q,g) \leq \sigma$. Therefore, we present an \textit{AND lower bound pruning} method, which effectively filters out candidate subgraphs with high AND values below.

%with different aggregation semantics

\begin{lemma}
    \label{lemma:AND_bound_pruning}
    {\bf (AND Lower Bound Pruning)} Given a candidate subgraph $g$, a query graph $q$, and an aggregated neighbor difference threshold $\sigma$, subgraph $g$ can be safely pruned, if it holds that $lb\_AND(q,g) > \sigma$, where $lb\_AND(q,g)$ is a lower bound of $AND(q,g)$.
    % For different aggregation semantics, we consider two cases below:
    % \begin{itemize}
    %     \item Case 1 (SUM): The candidate subgraph $g$ can be safely pruned, if it holds that: $lb\_AND(q,g) = \sum_{(q_j,v_i)}(lb\_ND(q_j,v_i)) > \sigma$.
    %     \item Case 2 (MAX): The candidate subgraph $g$ can be safely pruned, if it holds that: $lb\_AND(q,g) = \max(\forall_{(q_j,v_i)} lb\_ND(q_j,v_i)) > \sigma$.
    % \end{itemize}
\end{lemma}
\begin{proof}
Since $lb\_AND(q,g)$ is a lower bound of the aggregated neighbor difference $AND(q,g)$, we have $AND(q,g) \geq lb\_AND(q,g)$. From the lemma assumption that $lb\_AND(q,g) > \sigma$ holds, by the inequality transition, it holds that $AND(q,g) \geq lb\_AND(q,g) > \sigma$. Thus, from Definition~\ref{def:S3AND}, candidate subgraph $g$ cannot be the S$^3$AND answer and can be safely pruned, which completes the proof.
\end{proof}


