{\color{black}
\noindent{\bf Discussions on How to Compute an AND Lower Bound,\\ $lb\_AND(q,g)$: } Based on Eq.~(\ref{eq:AND}), in order to compute a lower bound, $lb\_AND(q,g)$, of the AND score $AND(q,g)$, we only need to obtain a lower bound, $lb\_ND(q_j, v_i)$, of the neighbor difference $ND(q_j, v_i)$ (as given in Eq.~(\ref{eq:ND})) for each matching vertex pair $(q_j, v_i)$. This way, we have: 
% $$lb\_AND(q,g)=f\left(\left\{ lb\_ND(q_j, v_i) | \forall (q_j, v_i), s.t. M(q_j) = v_i \right\}\right).$$
\begin{equation}
    lb\_AND(q,g)=f\left(\left\{ lb\_ND(q_j, v_i) | \forall (q_j, v_i), s.t. M(q_j) = v_i \right\}\right).
    \label{eq:lb_AND}
\end{equation}

\underline{\it The Computation of the Neighbor Difference Lower Bound}\\ \underline{$lb\_ND(q_j, v_i)$.} To compute a lower bound $lb\_ND(q_j, v_i)$ of the neighbor difference $ND(q_j, v_i)$, we can rewrite the neighbor difference $ND(q_j, v_i)$ in Eq.~(\ref{eq:ND}) as follows: 
\begin{eqnarray}
ND(q_j, v_i)&=&|\mu(N(q_j)) - N(v_i)|\label{eq:ND2} \\
&=&|\mu(N(q_j))|-|\mu(N(q_j)) \cap N(v_i)|.  \notag
\end{eqnarray}


In Eq.~(\ref{eq:ND2}), the first term $|\mu(N(q_j))|$ is a constant during online S$^3$AND query processing (i.e., the number of vertex $q_j$'s neighbors in the query graph $q$). Thus, in order to calculate the ND lower bound $lb\_ND(q_j, v_i)$, we alternatively need to compute an upper bound of the second term in Eq.~(\ref{eq:ND2}) (i.e., $|\mu(N(q_j)) \cap N(v_i)|$). Since $N(v_i) \supseteq (\mu(N(q_j)) \cap N(v_i))$ holds, we can obtain its upper bound: $|N(v_i)| \geq |\mu(N(q_j)) \cap N(v_i)|$. 


In other words, we have the ND lower bound below: 
\begin{eqnarray}
lb\_ND(q_j, v_i) = \max\{0, |\mu(N(q_j))| - |N(v_i)|\}.
\label{eq:lb_ND1}
\end{eqnarray}

%... ... {\bf [please complete this part!]} {\color{blue} $N(v_i)$ is not necessarily a subset of $\mu(N(q_j))$.}

\underline{\it The Computation of a Tighter Neighbor Difference Lower Bound}\\ \underline{$lb\_ND(q_j, v_i)$.} Note that, some neighbors, $q_l$, of query vertex $q_j$ may not match with that, $v_l$, of data vertex $v_i$ with respect to their keyword sets (i.e., $q_l.W \nsubseteq v_l.W$).
Therefore, $|N(v_i)|$ may not be a tight upper bound of $|\mu(N(q_j)) \cap N(v_i)|$, and in turn $lb\_ND(q_j, v_i)$ in Eq.~(\ref{eq:lb_ND1}) is not a tight neighbor difference lower bound.

Below, we will consider the keyword set matching between (neighbors of) vertices $v_i$ and $q_j$, and derive a tighter neighbor difference lower bound. 
Specifically, for each neighbor $q_l$ of query vertex $q_j$, if its keyword set $q_l.W$ is a subset of the union of keyword sets from $N(v_i)$ (i.e., $v_i$'s neighbors), we can count 1, for the upper bound of $|\mu(N(q_j)) \cap N(v_i)|$). Formally, we have this upper bound given by: 
\begin{eqnarray}
\sum_{q_l\in N(q_j)} \Phi\left(q_l.W \subseteq \cup_{\forall v_l \in N(v_i)} v_l.W\right) \geq |\mu(N(q_j)) \cap N(v_i)|,\notag
\end{eqnarray}
where $\Phi(\cdot)$ is an indicator function (i.e., $\Phi(z) = 1$, if $z$ is \textit{true}; $\Phi(z) = 0$, otherwise).


As a result, we can obtain a tighter ND lower bound below:
\begin{equation}
    lb\_ND(q_j,v_i) = |\mu(N(q_j))|- \hspace{-3ex}\sum_{q_l\in N(q_j)} \hspace{-3ex}\Phi\left(q_l.W \subseteq \cup_{\forall v_l \in N(v_i)} v_l.W\right).\label{eq:lb_ND2}
\end{equation}

To efficiently check the containment of two keyword sets in Eq.~(\ref{eq:lb_ND2}) (i.e., $q_l.W \subseteq \cup_{\forall v_l \in N(v_i)} v_l.W$), we can also use their keyword bit vectors to replace the parameter of the indicator function $\Phi(\cdot)$ in  Eq.~(\ref{eq:lb_ND2}), that is,
\begin{eqnarray}
    &&\hspace{-5ex}lb\_ND(q_j, v_i) = |\mu(N(q_j))| \label{eq:lb_ND3}\\
    &&- \hspace{-2ex}\sum_{q_l\in N(q_j)} \hspace{-1ex}\Phi\left(\bigwedge_{x=1}^{m} \left( q_l.BV^{(x)} \bigwedge \left(\bigvee_{\forall v_l \in N(v_i)} v_l.BV^{(x)}\right) = q_l.BV^{(x)}\right)\right),\hspace{-3ex}\notag
\end{eqnarray}
where $\land$ and $\lor$ are bit-AND and bit-OR operators between two bit vectors, respectively.

\noindent {\bf ND Lower Bound Pruning for Individual Vertices:} Note that, Lemma~\ref{lemma:AND_bound_pruning} uses AND lower bound, $lb\_AND(q, g)$, to prune the entire candidate subgraphs $g$ (which are however not available during the filtering phase). Therefore, in the sequel, we will discuss how to utilize ND lower bounds, $lb\_ND(q_j, v_i)$ (w.r.t. individual vertices $v_i$), to filter out false alarms of vertices $v_i$ (or retrieve candidate vertices $v_i$), for different aggregation functions $f(\cdot)$ (e.g., $MAX$ or $SUM$).

