\noindent
\textbf{The Data Structure of Index $\mathcal{I}$:}
We will construct a tree index $\mathcal{I}$ on the data graph $G$.
Specifically, the tree index $\mathcal{I}$ contains two types of nodes, leaf and non-leaf nodes.

\underline{\textit{Leaf Nodes:}} 
Each leaf node $\mathcal{N}$ contains a vertex set in the data graph $G$. Each vertex $v_i$ is associated with the following pre-computed data in $v_i.Aux$:

\begin{itemize}[noitemsep, topsep=1pt, partopsep=1pt, itemsep=1pt, parsep=1pt]
    % \item a keyword bit vector, $v_i.BV$;
    \item $m$ keyword bit vectors, $v_i.BV^{(x)}$ (for $1 \leq x \leq m$);
    \item $m$ neighbor keyword bit vectors, $v_i.NBV^{(x)}$ (for $1 \leq x \leq m$), and;
    \item the number of distinct neighbor keywords, $v_i.nk$.
\end{itemize}

\underline{\textit{Non-Leaf Nodes:}}
Each non-leaf node $\mathcal{N}$ has multiple entries $\mathcal{N}_i$, each corresponding to a subgraph of $G$.
Each entry $\mathcal{N}_i$ is associated with the following aggregates:

\begin{itemize}[noitemsep, topsep=1pt, partopsep=1pt, itemsep=1pt, parsep=1pt]
    \item a pointer to a child node, 
    $\mathcal{N}_i.ptr$;
    % \item an aggregated keyword bit vector, $\mathcal{N}_i.BV =\lor_{\forall v_l \in \mathcal{N}_i} v_l.BV$;
    \item $m$ aggregated keyword bit vectors, $\mathcal{N}_i.BV^{(x)}$\\ $=$ $\lor_{\forall v_l \in \mathcal{N}_i} v_l.BV^{(x)}$ (for $1 \leq x \leq m$);
    \item $m$ aggregated neighbor keyword bit vectors, 
    $\mathcal{N}_i.NBV^{(x)} = \lor_{\forall v_l \in \mathcal{N}_i} v_l.NBV^{(x)}$  (for $1 \leq x \leq m$), and;
    \item the maximum number of distinct neighbor keywords for vertices $v_l$ under entry $\mathcal{N}_i$, that is,
    $\mathcal{N}_i.nk = \max_{\forall v_l \in \mathcal{N}_i} v_l.nk$.
\end{itemize}
