\noindent
\textbf{Index-Level ND-Lower-Bound-Based Pruning:} We also propose an index-level candidate node retrieval based on ND lower bounds (via Corollary~\ref{coro:ND_pruning_MAX_SUM}) below. 

%to access the entry $\mathcal{N}_i$ with low ND value.

\begin{lemma}
    \label{lemma:index_lb_ND_pruning}
    {\bf (Index-Level ND-Lower-Bound-Based Pruning)} Given an index entry $\mathcal{N}_i$, a query vertex $q_j$, and an aggregate threshold $\sigma$, index entry $\mathcal{N}_i$ can be safely pruned with respect to $q_j$, if $lb\_ND(q_j, \mathcal{N}_i) > \sigma$ holds, where we have $lb\_ND(q_j, \mathcal{N}_i)$  $=\min_{\forall v \in \mathcal{N}_i}$ $\{lb\_ND(q_j, v)\}$.
\end{lemma}
\begin{proof} (Proof by Contradiction) Assume that some vertex $v$ under index entry $\mathcal{N}_i$ is in an S$^3$AND subgraph answer $g$. Since it holds that $lb\_ND(q_j, \mathcal{N}_i)$ $=\min_{\forall v \in \mathcal{N}_i}\{lb\_ND(q_j, v)\}$, we have $lb\_ND(q_j, v) \geq lb\_ND(q_j, \mathcal{N}_i)$. Moreover, from the lemma assumption that $lb\_ND(q_j, \mathcal{N}_i) > \sigma$, by the inequality transition, we have $lb\_ND(q_j, v) > \sigma$. From Eq.~(\ref{eq:lb_AND}), for either $f=MAX$ or $f=SUM$, we always have $lb\_AND(q, g) = f(f(lb\_ND(q_j, v') | \forall v'\in V(g)\textbackslash\{v\}), lb\_ND(q_j, v)) > \sigma$, which contradicts with our initial assumption that vertex $v$ is in the subgraph answer $g$. Therefore, we can prune all vertices under entry $\mathcal{N}_i$ with respect to $q_j$.
\end{proof}

