\begin{algorithm}[t]
    \caption{\bf Online S$^3$AND Query Processing}
    \label{alg:online}
    \KwIn{
        \romannumeral1) a data graph $G$,
        \romannumeral2) a query graph $q$,
        \romannumeral3) an aggregate threshold $\sigma$, 
        \romannumeral4) an aggregation function $f(\cdot)$, and
        \romannumeral5) the index $\mathcal{I}$ over $G$ 
    }
    \KwOut{a set, $S$, of subgraphs in $G$ similar to $q$ under AND semantics}

