    % \end{equation}
    \begin{equation}
    \label{eqn:Benign_Features_Restoration_pipeline}
    	[H_{img}^{l+1}, H_{ins}^{l+1}, H_{safe}^{l+1}] = 
       \textrm{FFN}^{l}(\textrm{Attention}^{l}([SH_{img}^{l}, SH_{ins}^{l}, H_{safe}^{l}]),  l=n+\Delta_n. 
    \end{equation}
