    %     [SH_{image}^{l+1}, SH_{instruction}^{l+1}, SH_{safe}^{l+1}] = \textrm{FFN}^{l}(\textrm{Attention}^{l}([ \hat{H}_{image}^{l}, H_{instruction}^{l}, H_{safe}^{l}]), l \in \mathcal{L},
    % \end{equation}
