    \vspace{-3mm}
    \begin{equation}
    \label{eqn:restore_token}
    	BFR(\hat{H}_{img}^{n + \Delta_n - 1}, H_{img}^{n + \Delta_n - 1}) = \{(h_i, i) | h_i = \begin{cases}
